//! Chat completion + tool calling adapter layer for BYOP mode (built on genai 0.5.3).
//!
//! Translates `RequestParams` into a genai `ChatRequest`, calls the user-configured
//! provider through `Client::exec_chat_stream`, and translates the response back into
//! `warp_multi_agent_api::ResponseEvent`. The controller's own logic (permissions/dialogs/
//! execution/result write-back/triggering the next turn) takes over the closed loop from there.
//!
//! ## Explicit routing across 5 API protocols
//!
//! Instead of forcing every provider through an OpenAI-compatible shim, `ServiceTargetResolver`
//! maps the `AgentProviderApiType` the user picked in the settings UI one-to-one onto genai's
//! `AdapterKind`:
//!
//! | ApiType        | AdapterKind  | Default endpoint                                |
//! |----------------|--------------|------------------------------------------------|
//! | OpenAi         | OpenAI       | https://api.openai.com/v1                      |
//! | OpenAiResp     | OpenAIResp   | https://api.openai.com/v1 (via /v1/responses)  |
//! | Gemini         | Gemini       | https://generativelanguage.googleapis.com/v1beta |
//! | Anthropic      | Anthropic    | https://api.anthropic.com/v1 (via /v1/messages) |
//! | Ollama         | Ollama       | http://localhost:11434                         |
//!
//! The user-provided `base_url` always overrides the default. This means:
//! - OpenAI-compatible providers like DeepSeek / SiliconFlow / OpenRouter pick `OpenAi` with a
//!   custom base_url
//! - Explicitly selecting the adapter completely bypasses genai's default "guess by model name"
//!   behavior, avoiding misdetection
//!
//! ## Multi-turn message conversion
//!
//! - system prompt: `ChatRequest::with_system()` (not added to the messages array)
//! - user query: `ChatMessage::user(text)`
//! - assistant text: `ChatMessage::assistant(text)`
//! - assistant tool_calls: `ChatMessage::from(Vec<ToolCall>)` (automatic assistant role)
//! - tool result: `ChatMessage::from(ToolResponse::new(call_id, content))` (automatic tool role)
//!
//! ## Streaming implementation
//!
//! `Client::exec_chat_stream` returns a `ChatStreamResponse` whose `stream` field implements
//! `futures_core::Stream<Item = Result<ChatStreamEvent>>`. Events:
//! - `Start` / `Chunk(text)` / `ReasoningChunk(text)` / `ToolCallChunk(tool_call)` / `End(StreamEnd)`
//!
//! For Chunk/ReasoningChunk we immediately emit `AppendToMessageContent` (typewriter effect);
//! for ToolCallChunk we accumulate a buffer (keyed by call_id) and emit a single
//! `Message::ToolCall` at the end of the stream, which the controller then takes over
//! automatically.

