// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
// The system prompt is generated by `prompt_renderer::render_system` via a minijinja
// template, choosing system/{anthropic,gpt,beast,gemini,kimi,codex,trinity,default}.j2
// based on the LLMId model family, and rendering the AIAgentContext already collected by
// the warp client (env / git / skills / project_rules / codebase / current_time) into the
// system prompt, so the BYOP path gets environment information on par with warp's own path.

use super::attachment_caps;
use super::prompt_renderer;
use super::user_context;
use crate::ai::agent::AIAgentContext;

/// Extracts the most recent `UserQuery.context` from input (equivalent to what warp's
/// `convert_to.rs::convert_input` picks up). The conversation-level "last known-good env
/// context".
///
/// For requests like tool result / auto-resume, `params.input` is **empty** (observed
/// `system_ctx inputs=0 ctx_len=0`) — the whole turn is driven entirely by persisted
/// history, with no input carrying any context. `latest_input_context` can therefore only
/// return an empty slice, and `collect_prompt_context` renders an <env> section that's
/// entirely default values from that empty slice (`Working directory: none`, no Shell/Platform
/// lines, 9303 bytes), while the user-question turn renders the full version (9370 bytes) —
/// message[0] flip-flops between the two. FLM's per-entry checksum comparison then mismatches
/// right at entry 0 (`matched 0`), forcing a full re-prefill every turn.
///
/// The controller side has actually already computed the correct env (see
/// `controller/input_context.rs::input_context_for_request`; the log line
/// `env_context ... resolved_pwd=Some("/home/winters")` is correct every turn) — there's
/// just no carrier to bring it here. So we remember the last non-empty context per
/// conversation, and fall back to it when input is empty, keeping message[0] byte-for-byte
/// stable.
static CONVERSATION_SYSTEM_CTX: std::sync::Mutex<
    Option<(crate::ai::agent::conversation::AIConversationId, Vec<AIAgentContext>)>,
> = std::sync::Mutex::new(None);

/// Returns the most recent input that **has a non-empty context**.
///
/// Previously this only checked whether `context()` was `Some`, but an empty `Vec` is also
/// `Some(&[])` — as soon as the last input's context was empty, it would immediately return
/// an empty slice, and an earlier input carrying the full env context would never be seen at
/// all. Consequence: `collect_prompt_context` gets an empty slice, and the system prompt's
/// <env> section degrades entirely to default values (`Working directory: none`, no
/// Shell/Platform lines), which doesn't match the 9370-byte version from the user-question
/// turn → message[0] changes every turn → both the upstream prompt cache and the local KV
/// cache inevitably miss (observed on a local 9B model: roughly 33s of extra full re-prefill
/// per turn).
///
/// An empty context carries no information, so skipping it and continuing to search backward
/// can never make things worse.
fn latest_input_context(input: &[AIAgentInput]) -> &[AIAgentContext] {
    for i in input.iter().rev() {
        if let Some(ctx) = i.context() {
            if !ctx.is_empty() {
                return ctx;
            }
        }
    }
    &[]
}

/// Renders the `<attached_running_command>` XML block for the LRC tag-in scenario, prepended
/// to the user message so the model can see the current PTY's actual state (command, grid
/// contents, whether it's an alt-screen), and thus correctly choose the
/// `write_to_long_running_shell_command` tool to send the appropriate key sequence.
fn render_running_command_context(rc: &RunningCommand) -> String {
    format!(
        "<attached_running_command command_id=\"{}\" is_alt_screen_active=\"{}\">\n  \
         <command>{}</command>\n  \
         <snapshot>\n{}\n  </snapshot>\n  \
         <instructions>This command is already running in the user's terminal. \
         Use `read_shell_command_output` with this command_id to inspect it, and \
         `write_to_long_running_shell_command` with this command_id to operate the program \
         through its PTY (in raw mode, use tokens like `<ESC>` and `<ENTER>` for control \
         keys). This command_id is valid even if the process was started by the user \
         rather than by run_shell_command. Do NOT spawn a new shell to control the same TUI.\
         </instructions>\n\
         </attached_running_command>",
        xml_attr(rc.block_id.as_str()),
        rc.is_alt_screen_active,
        xml_text(&rc.command),
        xml_text(&rc.grid_contents),
    )
}

/// Short fallback version: only the command_id is available (no full RunningCommand
/// snapshot), so the model at least knows the target PTY's id and can use
/// `read_shell_command_output` itself to fetch the latest contents.
fn render_running_command_id_context(command_id: &str) -> String {
    format!(
        "<attached_running_command command_id=\"{}\">\n  \
         <instructions>This command is already running in the user's terminal. \
         Use `read_shell_command_output` with this command_id to inspect it, and \
         `write_to_long_running_shell_command` with this command_id to operate the program \
         through its PTY. Do NOT spawn a new shell to control the same TUI.</instructions>\n\
         </attached_running_command>",
        xml_attr(command_id),
    )
}

fn render_lrc_request_context(params: &RequestParams) -> Option<String> {
    params
        .lrc_running_command
        .as_ref()
        .map(render_running_command_context)
        .or_else(|| {
            params
                .lrc_command_id
                .as_deref()
                .map(render_running_command_id_context)
        })
}

/// Zap: renders the SSH session status block, appended to the end of the system prompt.
///
/// Trigger condition: `SessionContext.is_legacy_ssh()` is true (the user typed
/// `ssh xx@xx` by hand in the local PTY to get into a remote host that doesn't have the
/// warp shell hook installed). In this kind of session:
/// - `session_type` is still `Local`
/// - the whole system prompt's [Environment] block describes the **local client's** OS/shell,
///   while the PTY is actually currently running on the **remote host**
///
/// Without proactively telling the model this, the LLM will infer from the local OS in the
/// system prompt that "the target is remote, I need to ssh there first," and will output a
/// doubly-nested command like `ssh xx@xx uname -a`.
///
/// Note: warpified SSH (`SessionType::WarpifiedRemote`) is not handled here — on that path
/// the remote shell hook has already re-bootstrapped, so host_info / shell are already the
/// remote's true values and the prompt is already correct as-is.
fn render_ssh_session_block(
    session_context: &crate::ai::blocklist::SessionContext,
) -> Option<String> {
    if !session_context.is_legacy_ssh() {
        return None;
    }
    let info = session_context.ssh_connection_info();
    let host = info
        .and_then(|i| i.host.as_deref())
        .map(xml_attr)
        .unwrap_or_else(|| "unknown".to_owned());
    let port = info
        .and_then(|i| i.port.as_deref())
        .map(xml_attr)
        .unwrap_or_else(|| "22".to_owned());

    Some(format!(
        "\n\n<ssh_session host=\"{host}\" port=\"{port}\">\n  \
         <fact>The active terminal PTY is currently inside an SSH session opened by the user from their local machine. \
         All shell commands you run via `run_shell_command` execute on the REMOTE host, not on the local client.</fact>\n  \
         <warning>The [Environment] block (OS / shell / working directory) above describes the LOCAL client and may not match the remote host. \
         If you need precise remote info, probe it directly (e.g. `uname -a`, `cat /etc/os-release`, `pwd`).</warning>\n  \
         <rules>\n    \
         - Run commands DIRECTLY (e.g. `uname -a`, `ls /`). Do NOT prepend `ssh {host} ...` — that opens a NESTED ssh session inside the current one.\n    \
         - Treat the working directory and home directory shown above with skepticism; they may reflect the local client.\n    \
         - When LRC tag-in mode is active (an `<attached_running_command>` block is present), prefer `write_to_long_running_shell_command` with that command_id to inject keystrokes into this same remote PTY. Spawning a new shell would create a separate local-side ssh client, not interact with the remote process the user is watching.\n  \
         </rules>\n\
         </ssh_session>"
    ))
}

/// XML-escapes the string while also stripping any illegal/problematic control characters,
/// to avoid JSON serialization failures.
///
/// `grid_contents` (the alt-screen content extracted from
/// `formatted_terminal_contents_for_input`) may contain raw ANSI escape sequences (0x1b),
/// CSI sequences, SGR codes, box-drawing chars, etc. Control characters `< 0x20` among these
/// make Anthropic's JSON parser report "invalid escaped character in string", because JSON
/// RFC 7159 only accepts the escapes `\b \f \n \r \t \" \\ \/ \uXXXX` — anything else like
/// `\v` `\a` `\x1b` is rejected outright.
///
/// Handling:
/// - `\n` `\r` `\t` are kept (valid in JSON)
/// - other `< 0x20` control characters are replaced with a space (purely for display to the
///   model; there's no need to preserve ANSI colors etc.)
/// - `&` `<` `>` are converted to XML entities
fn xml_text(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\n' | '\r' | '\t' => out.push(c),
            c if (c as u32) < 0x20 => out.push(' '),
            // DEL (0x7f) handled separately — also a control character
            '\u{7f}' => out.push(' '),
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

fn xml_attr(s: &str) -> String {
    xml_text(s).replace('"', "&quot;")
}

// ---------------------------------------------------------------------------
// Multi-turn message conversion
// ---------------------------------------------------------------------------

/// Accumulates the text + tool_calls + reasoning for the same assistant turn, then flushes
/// them into one or two `ChatMessage`s (one for text, one for tool_calls — genai models them
/// as separate messages).
///
/// **thinking-mode reasoning_content echo-back gate** (bidirectional).
///
/// `force_echo_reasoning` controls two things at once, with unified semantics of "this
/// model's capability declares `interleaved.field = reasoning_content`" (aligned with
/// opencode's `model.capabilities.interleaved`):
///
/// - `true` (model_id matches an entry in the `reasoning::INTERLEAVED_RULES` substring
///   table — DeepSeek / Kimi / MiMo / Qwen3 / GLM thinking / MiniMax / Hunyuan / Ernie /
///   Doubao / Yi, etc.; or api_type is the DeepSeek adapter as a whole): every assistant
///   message must carry `reasoning_content` (use the real reasoning if present, otherwise
///   attach a non-empty placeholder) — this satisfies the thinking-mode server's "field
///   must be present" validation.
/// - `false` (everything else): **discard it on replay even if the stream received real
///   reasoning_content this turn** — don't attach `with_reasoning_content` to the historical
///   assistant message.
///
/// Why we proactively discard real reasoning even in the `false` case: many
/// OpenAI-strict providers treat `messages[].reasoning_content` as an illegal field and
/// return 400 (`code: wrong_api_format`):
///
/// - **Cerebras** (the culprit behind zerx-lab/warp #25, a second-turn 400 on zai-glm-4.7)
/// - **Groq** (uses `reasoning_format` / `include_reasoning` at the protocol level instead,
///   doesn't accept a message field)
/// - **OpenRouter / Together AI / SambaNova / Anyscale / Replicate** and other
///   relay/inference vendors
/// - **OpenAI official** (GPT-5/o-series go through OpenAIResp; o-series uses
///   `reasoning.encrypted_content` and doesn't accept `reasoning_content`)
///
/// genai 0.6's OpenAI adapter (`adapter_shared.rs:367,385-387`) **unconditionally** hoists
/// a top-level `reasoning_content` field whenever it sees `ContentPart::ReasoningContent`,
/// so the gate has to be moved forward to the client side — i.e. "if we don't attach a
/// ContentPart, it can't be serialized."
///
/// The Anthropic / Gemini adapter's serialization layer ignores
/// `ContentPart::ReasoningContent` (each uses its own thinking blocks / thought signature
/// instead), so they're unaffected by this gate, but for consistency we still take the
/// `false` branch and don't attach it there either.
const REASONING_ECHO_PLACEHOLDER: &str = " ";

#[derive(Default)]
struct AssistantBuffer {
    text: Option<String>,
    tool_calls: Vec<ToolCall>,
    tool_call_keys: Vec<ToolCallKey>,
    /// The previous turn's AgentReasoning (thinking chain). Attached to the corresponding
    /// assistant message's reasoning_content field on flush (genai serializes it per
    /// adapter internally: DeepSeek/Kimi use reasoning_content, Anthropic uses thinking
    /// blocks).
    reasoning: Option<String>,
    /// Whether the thinking-mode adapter forces echoing back reasoning_content (non-empty
    /// placeholder). Decided by `super::reasoning::model_requires_reasoning_echo`.
    force_echo_reasoning: bool,
}

impl AssistantBuffer {
    fn new(force_echo_reasoning: bool) -> Self {
        Self {
            force_echo_reasoning,
            ..Default::default()
        }
    }

    fn push_tool_call(&mut self, tool_call: ToolCall, key: ToolCallKey) {
        self.tool_calls.push(tool_call);
        self.tool_call_keys.push(key);
    }

    fn flush_into(&mut self, messages: &mut Vec<ChatMessage>) {
        let _ = self.flush_into_with_group(messages);
    }

    fn flush_into_with_group(
        &mut self,
        messages: &mut Vec<ChatMessage>,
    ) -> Option<OutboundAssistantToolGroup> {
        let reasoning = self.reasoning.take();
        let has_tool_calls = !self.tool_calls.is_empty();
        // Decide the reasoning string to attach to the assistant message for this flush.
        //
        // **Gate inversion**: when `force_echo_reasoning = false`, **never attach it**, even
        // if the stream received real reasoning this turn (thinking models like zai-glm /
        // qwen3-thinking emit a reasoning_content chunk when going through the
        // OpenAI-compatible path) — because OpenAI-strict providers like Cerebras / Groq /
        // OpenRouter return a flat 400 `wrong_api_format` when they see
        // `messages[].reasoning_content` (zerx-lab/warp #25).
        //
        // When `force_echo_reasoning = true` (DeepSeek api_type / OpenAI+kimi/moonshot):
        // - real reasoning present → use it
        // - none → non-empty placeholder (satisfies the "field must be present" validation)
        let echo_reasoning: Option<String> = if self.force_echo_reasoning {
            match reasoning {
                Some(r) if !r.is_empty() => Some(r),
                _ => Some(REASONING_ECHO_PLACEHOLDER.to_owned()),
            }
        } else {
            // Note: discarded even if `reasoning` is Some(non-empty) — see the gate
            // inversion explanation above.
            None
        };
        if let Some(t) = self.text.take() {
            let mut msg = ChatMessage::assistant(t);
            if has_tool_calls {
                // DeepSeek thinking mode requires every assistant message to carry
                // reasoning_content. When genai models text + tool_calls as two separate
                // assistant messages, the text one also needs the placeholder filled in.
                if self.force_echo_reasoning {
                    msg = msg.with_reasoning_content(Some(REASONING_ECHO_PLACEHOLDER.to_owned()));
                }
            } else if let Some(r) = echo_reasoning.clone() {
                msg = msg.with_reasoning_content(Some(r));
            }
            messages.push(msg);
        }
        if has_tool_calls {
            // genai's `From<Vec<ToolCall>> for ChatMessage` automatically produces the
            // assistant role + MessageContent::from_tool_calls.
            let mut msg = ChatMessage::from(std::mem::take(&mut self.tool_calls));
            if let Some(r) = echo_reasoning {
                msg = msg.with_reasoning_content(Some(r));
            }
            let message_index = messages.len();
            messages.push(msg);
            Some(OutboundAssistantToolGroup {
                message_index,
                tool_call_keys: std::mem::take(&mut self.tool_call_keys),
            })
        } else {
            self.tool_call_keys.clear();
            None
        }
    }
}

#[derive(Debug, Clone)]
struct OutboundAssistantToolGroup {
    message_index: usize,
    tool_call_keys: Vec<ToolCallKey>,
}

fn flush_assistant_buffer(
    buf: &mut AssistantBuffer,
    messages: &mut Vec<ChatMessage>,
    outbound_tool_groups: &mut Vec<OutboundAssistantToolGroup>,
) {
    if let Some(group) = buf.flush_into_with_group(messages) {
        if !group.tool_call_keys.is_empty() {
            outbound_tool_groups.push(group);
        }
    }
}

/// Builds a user `ChatMessage`, deciding whether to switch to the
/// `MessageContent::Parts(Text + Binary[])` multimodal form based on model capability.
///
/// - no binaries → take the old path, plain-text `ChatMessage::user(text)`, consistent with
///   P0 behavior
/// - binaries present and model supports the corresponding mime → `Parts(vec![Text(text),
///   Binary(...), ...])`, and the genai adapter automatically adapts it to the wire protocol
///   (OpenAI image_url/file, Anthropic image/document, Gemini inline_data, etc.)
/// - binaries present but model doesn't support it → log a warning, skip that part, and
///   degrade to plain text (the `<image .../>` / `<file binary=true .../>` placeholder in the
///   prefix XML is still there, so the LLM at least knows what the user attached)
fn build_user_message_with_binaries(
    text: String,
    binaries: Vec<user_context::UserBinary>,
    caps: attachment_caps::AttachmentCaps,
) -> ChatMessage {
    if binaries.is_empty() {
        return ChatMessage::user(text);
    }

    let mut parts: Vec<ContentPart> = Vec::with_capacity(1 + binaries.len());
    parts.push(ContentPart::Text(text));

    let mut error_replacements: Vec<(String, String)> = Vec::new();
    for bin in binaries {
        if !caps.supports_mime(&bin.content_type) {
            // Zap aligns with opencode's `unsupportedParts`
            // (packages/opencode/src/provider/transform.ts:305-341): an unsupported mime
            // isn't silently dropped — instead we insert an ERROR text part so the LLM tells
            // the user itself. The wording is copied verbatim from opencode's
            // `ERROR: Cannot read {name} (this model does not support {modality} input).
            // Inform the user.`, with modality mapped from the mime prefix and name
            // preferring the file name.
            let modality = mime_to_modality(&bin.content_type);
            let name = if bin.name.is_empty() {
                modality.to_string()
            } else {
                format!("\"{}\"", bin.name)
            };
            let err_text = format!(
                "ERROR: Cannot read {name} (this model does not support {modality} input). Inform the user."
            );
            error_replacements.push((bin.name.clone(), bin.content_type.clone()));
            parts.push(ContentPart::Text(err_text));
            continue;
        }
        parts.push(ContentPart::Binary(Binary::from_base64(
            bin.content_type,
            bin.data,
            Some(bin.name),
        )));
    }

    if !error_replacements.is_empty() {
        log::info!(
            "[byop] {} attachment(s) replaced with ERROR text — caps={caps:?} does not support: {error_replacements:?}",
            error_replacements.len()
        );
    }

    // If all binaries were replaced with ERROR text (no real Binary part remains), still
    // keep the ERROR text part so the model sees it. In the degenerate case (e.g. text is
    // empty and no part got added), fall back to plain text.
    if parts.len() == 1 {
        if let Some(ContentPart::Text(t)) = parts.into_iter().next() {
            return ChatMessage::user(t);
        }
        return ChatMessage::user("");
    }

    ChatMessage {
        role: ChatRole::User,
        content: MessageContent::from_parts(parts),
        options: None,
    }
}

/// MIME → modality string mapping. Aligns with opencode's `mimeToModality`
/// (packages/opencode/src/provider/transform.ts:12-18).
fn mime_to_modality(mime: &str) -> &'static str {
    let lower = mime.trim().to_ascii_lowercase();
    if lower.starts_with("image/") {
        "image"
    } else if lower.starts_with("audio/") {
        "audio"
    } else if lower.starts_with("video/") {
        "video"
    } else if lower == "application/pdf" {
        "pdf"
    } else {
        "file"
    }
}

/// Collects `params.tasks` into a stable, linear message sequence. Fixes Issue #94.
///
/// `params.tasks` comes from
/// [`crate::ai::agent::conversation::AIConversation::compute_active_tasks`], which collects
/// them via `HashMap::into_values()` → the order between tasks is non-deterministic. The
/// old implementation did a naive concatenation with `flat_map(|t| t.messages.iter())`,
/// which had two defects in multi-task scenarios (LRC CLI subagent / subtasks spawned by the
/// `subagent` tool):
///   1. The relative order between tasks was random → a historical turn's user message
///      could end up sorted to the end of the sequence and get mistaken by the upstream
///      model for "the latest turn's user message" (the direct symptom of Issue #94).
///   2. When an LRC subagent spawns, the current turn's UserQuery gets copied into **both**
///      the root task and the newly created subtask (see the subtask UserQuery injection in
///      the `generate_byop_output` stream — that copy is required for `CLISubagentView`
///      rendering and can't be removed at the source), so the naive concatenation would make
///      the same user query appear twice in the request.
///
/// Fix: do a DFS starting from the root task (no parent, or parent not in the tasks set),
/// and drill down into the corresponding subtask whenever a `Subagent` ToolCall is
/// encountered — the same deterministic traversal as
/// [`crate::ai::agent::task_store::TaskStore::all_linearized_messages`]; and dedupe
/// UserQuery entries by `(request_id, query)`, discarding the subtask copy produced by LRC.
/// Different user turns have different `request_id`s so they won't be mistakenly removed;
/// old data / test stubs where `request_id` is empty fall back to not deduping, to avoid
/// false positives. Orphan tasks not reached by the DFS are appended at the end sorted by
/// id, as a fallback to make sure no messages are lost.
fn collect_linearized_task_messages(tasks: &[api::Task]) -> Vec<&api::Message> {
    use std::collections::{HashMap, HashSet};

    if tasks.is_empty() {
        return Vec::new();
    }

    let by_id: HashMap<&str, &api::Task> = tasks.iter().map(|t| (t.id.as_str(), t)).collect();

    // root = a task with no parent, or whose parent isn't in the current tasks set.
    let root = tasks.iter().find(|t| match t.dependencies.as_ref() {
        None => true,
        Some(dep) => {
            dep.parent_task_id.is_empty() || !by_id.contains_key(dep.parent_task_id.as_str())
        }
    });

    fn push_msg<'a>(
        msg: &'a api::Message,
        out: &mut Vec<&'a api::Message>,
        seen_user_queries: &mut HashSet<(&'a str, &'a str)>,
    ) {
        if let Some(api::message::Message::UserQuery(u)) = &msg.message {
            if !msg.request_id.is_empty()
                && !seen_user_queries.insert((msg.request_id.as_str(), u.query.as_str()))
            {
                return;
            }
        }
        out.push(msg);
    }

    fn dfs<'a>(
        task: &'a api::Task,
        by_id: &HashMap<&'a str, &'a api::Task>,
        visited_tasks: &mut HashSet<&'a str>,
        out: &mut Vec<&'a api::Message>,
        seen_user_queries: &mut HashSet<(&'a str, &'a str)>,
    ) {
        if !visited_tasks.insert(task.id.as_str()) {
            return;
        }
        for msg in &task.messages {
            push_msg(msg, out, seen_user_queries);
            if let Some(api::message::Message::ToolCall(tc)) = &msg.message {
                if let Some(api::message::tool_call::Tool::Subagent(sub)) = &tc.tool {
                    if let Some(subtask) = by_id.get(sub.task_id.as_str()) {
                        dfs(subtask, by_id, visited_tasks, out, seen_user_queries);
                    }
                }
            }
        }
    }

    let mut out: Vec<&api::Message> = Vec::new();
    let mut visited_tasks: HashSet<&str> = HashSet::new();
    let mut seen_user_queries: HashSet<(&str, &str)> = HashSet::new();

    if let Some(root) = root {
        dfs(
            root,
            &by_id,
            &mut visited_tasks,
            &mut out,
            &mut seen_user_queries,
        );
    }

    // Orphan-task fallback: sort by id to guarantee determinism.
    let mut orphans: Vec<&api::Task> = tasks
        .iter()
        .filter(|t| !visited_tasks.contains(t.id.as_str()))
        .collect();
    orphans.sort_by(|a, b| a.id.cmp(&b.id));
    for task in orphans {
        if !visited_tasks.insert(task.id.as_str()) {
            continue;
        }
        for msg in &task.messages {
            push_msg(msg, &mut out, &mut seen_user_queries);
        }
    }

    out
}

struct SerializerProjectionBuilder {
    items: Vec<ProjectionItem>,
    pending_tool_calls: Vec<ProjectedToolCall>,
    pending_task_id: Option<String>,
    pending_assistant_message_id: Option<String>,
    skipped_tool_results: HashSet<(String, String)>,
    /// `(task_id, tool_call_id)` → the assistant message id that made that call.
    ///
    /// The projection is built by **traversing the real messages in order**, so which
    /// assistant message made which tool call is a known fact — no need to guess after the
    /// fact. `normalize_projection`'s backward-inference gives up as soon as it hits a
    /// boundary (that's its intentionally conservative design), and an assistant's
    /// plain-text `AgentOutput` can happen to be persisted between a ToolCall and its
    /// ToolCallResult, causing the result to lose its ownership, get judged as
    /// `OutOfOrderToolResult`, and permanently block the conversation. So we record the fact
    /// directly here for the result to look up.
    tool_call_owner: HashMap<(String, String), String>,
}

impl SerializerProjectionBuilder {
    fn new() -> Self {
        Self {
            items: Vec::new(),
            pending_tool_calls: Vec::new(),
            pending_task_id: None,
            pending_assistant_message_id: None,
            skipped_tool_results: HashSet::new(),
            tool_call_owner: HashMap::new(),
        }
    }

    /// Looks up the recorded owner of a tool call (so `push_tool_result` can fill it in
    /// precisely instead of relying on inference).
    fn owner_of(&self, task_id: &str, tool_call_id: &str) -> Option<String> {
        self.tool_call_owner
            .get(&(task_id.to_owned(), tool_call_id.to_owned()))
            .cloned()
    }

    fn push_user_boundary(&mut self, task_id: String, message_id: String) {
        self.flush_tool_calls();
        self.items
            .push(ProjectionItem::user_boundary(task_id, message_id));
    }

    fn push_assistant_boundary(&mut self, task_id: String, message_id: String) {
        self.flush_tool_calls();
        self.items
            .push(ProjectionItem::assistant_boundary(task_id, message_id));
    }

    fn push_tool_call(
        &mut self,
        task_id: &str,
        message_id: &str,
        tool_call: &api::message::ToolCall,
    ) {
        use crate::ai::agent::task::helper::ToolCallExt;

        if tool_call.subagent().is_some() {
            self.skipped_tool_results
                .insert((task_id.to_owned(), tool_call.tool_call_id.clone()));
            return;
        }

        if self
            .pending_task_id
            .as_deref()
            .is_some_and(|pending_task_id| pending_task_id != task_id)
        {
            self.flush_tool_calls();
        }

        if self.pending_tool_calls.is_empty() {
            self.pending_task_id = Some(task_id.to_owned());
            self.pending_assistant_message_id = Some(message_id.to_owned());
        }

        let assistant_message_id = self
            .pending_assistant_message_id
            .clone()
            .unwrap_or_else(|| message_id.to_owned());
        self.tool_call_owner.insert(
            (task_id.to_owned(), tool_call.tool_call_id.clone()),
            assistant_message_id.clone(),
        );
        self.pending_tool_calls.push(ProjectedToolCall::new(
            task_id,
            assistant_message_id,
            tool_call.tool_call_id.clone(),
            redacted_tool_kind_for_tool_call(tool_call),
        ));
    }

    fn push_tool_result(&mut self, result: ProjectedToolResult) {
        self.flush_tool_calls();
        self.items.push(ProjectionItem::tool_result(result));
    }

    fn should_skip_tool_result(&self, task_id: &str, tool_call_id: &str) -> bool {
        self.skipped_tool_results
            .contains(&(task_id.to_owned(), tool_call_id.to_owned()))
    }

    fn finish(mut self) -> Vec<ProjectionItem> {
        self.flush_tool_calls();
        self.items
    }

    fn flush_tool_calls(&mut self) {
        if self.pending_tool_calls.is_empty() {
            return;
        }

        let task_id = self.pending_task_id.take().unwrap_or_default();
        let assistant_message_id = self.pending_assistant_message_id.take().unwrap_or_default();
        self.items.push(ProjectionItem::assistant_tool_calls(
            task_id,
            assistant_message_id,
            std::mem::take(&mut self.pending_tool_calls),
        ));
    }
}

fn redacted_tool_kind_for_tool_call(tool_call: &api::message::ToolCall) -> RedactedToolKind {
    use crate::ai::agent::task::helper::ToolExt;

    tool_call
        .tool
        .as_ref()
        .map(|tool| RedactedToolKind::new(tool.name()))
        .unwrap_or_default()
}

/// Cap (in characters) on outbound ToolResponse content.
///
/// Guards against abnormally huge tool output (e.g. an unbounded file_glob scanning an
/// entire home directory, or extremely long command output) blowing up the request: a
/// small-context local model's server (e.g. 32K) will flatly reject it or cut the stream
/// off instantly; worse, once such content is persisted, **every subsequent request** in
/// that conversation exceeds the limit, permanently bricking the conversation. Truncation
/// only happens at the request-building layer (the projection sent upstream) — the
/// persisted history is left untouched — so a historical conversation already poisoned by a
/// huge result gets "detoxified" at this layer and can keep being used.
const MAX_TOOL_RESPONSE_CHARS: usize = 40_000;

fn cap_tool_response_content(content: String) -> String {
    // Byte count >= char count, so short-circuit first on the cheap byte length.
    if content.len() <= MAX_TOOL_RESPONSE_CHARS {
        return content;
    }
    let total_chars = content.chars().count();
    if total_chars <= MAX_TOOL_RESPONSE_CHARS {
        return content;
    }
    let truncated: String = content.chars().take(MAX_TOOL_RESPONSE_CHARS).collect();
    format!(
        "{truncated}\n…[tool output truncated: sent {MAX_TOOL_RESPONSE_CHARS} of \
         {total_chars} chars; narrow the tool's scope (patterns/limit/path) and retry \
         if you need the rest]"
    )
}

fn current_input_result_kind(result: &AIAgentActionResult) -> TerminalResultKind {
    if result.result.is_cancelled() {
        TerminalResultKind::Cancellation
    } else {
        TerminalResultKind::Real
    }
}

fn persisted_tool_result_kind(
    msg: &api::Message,
    compacted_tool_msg_ids: Option<&std::collections::HashSet<String>>,
) -> TerminalResultKind {
    if compacted_tool_msg_ids.is_some_and(|ids| ids.contains(&msg.id)) {
        return TerminalResultKind::Compacted;
    }

    let Some(api::message::Message::ToolCallResult(tool_call_result)) = msg.message.as_ref() else {
        return TerminalResultKind::Real;
    };
    if tool_call_result.result.is_some() {
        return TerminalResultKind::Real;
    }

    let content = msg.server_message_data.trim();
    if content.is_empty() {
        return TerminalResultKind::Real;
    }

    match serde_json::from_str::<Value>(content) {
        Ok(value) => {
            if value
                .get("_byop_intercepted")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                TerminalResultKind::LocalInterception
            } else if value.get("error").and_then(Value::as_str) == Some("invalid_arguments") {
                TerminalResultKind::StructuredError
            } else {
                TerminalResultKind::Real
            }
        }
        Err(_)
            if content.contains("_byop_intercepted") || content.contains("invalid_arguments") =>
        {
            TerminalResultKind::UnreadableLocalInterception
        }
        Err(_) => TerminalResultKind::Real,
    }
}

fn current_input_task_id(params: &RequestParams) -> String {
    params
        .byop_target_task_id
        .clone()
        .or_else(|| params.tasks.first().map(|task| task.id.clone()))
        .unwrap_or_else(|| "current_input".to_owned())
}

fn build_serializer_readiness_projection(
    params: &RequestParams,
    all_msgs: &[&api::Message],
    summarize_head_end: Option<usize>,
    summary_inserts: &HashMap<String, String>,
    hidden_msg_ids: &std::collections::HashSet<String>,
    compacted_tool_msg_ids: &std::collections::HashSet<String>,
) -> Vec<ProjectionItem> {
    let mut builder = SerializerProjectionBuilder::new();

    for (idx, msg) in all_msgs.iter().enumerate() {
        if let Some(head_end) = summarize_head_end {
            if idx >= head_end {
                continue;
            }
        }

        if hidden_msg_ids.contains(&msg.id) {
            if summary_inserts.contains_key(&msg.id) {
                builder.push_user_boundary(msg.task_id.clone(), format!("summary_user:{}", msg.id));
                builder.push_assistant_boundary(
                    msg.task_id.clone(),
                    format!("summary_assistant:{}", msg.id),
                );
            }
            continue;
        }

        let Some(inner) = &msg.message else {
            continue;
        };

        match inner {
            api::message::Message::UserQuery(_) => {
                builder.push_user_boundary(msg.task_id.clone(), msg.id.clone());
            }
            api::message::Message::AgentOutput(_) => {
                builder.push_assistant_boundary(msg.task_id.clone(), msg.id.clone());
            }
            api::message::Message::AgentReasoning(_) => {}
            api::message::Message::ToolCall(tool_call) => {
                builder.push_tool_call(&msg.task_id, &msg.id, tool_call);
            }
            api::message::Message::ToolCallResult(tool_call_result) => {
                if builder.should_skip_tool_result(&msg.task_id, &tool_call_result.tool_call_id) {
                    continue;
                }
                let owner = builder.owner_of(&msg.task_id, &tool_call_result.tool_call_id);
                builder.push_tool_result(ProjectedToolResult::new(
                    msg.task_id.clone(),
                    msg.id.clone(),
                    owner,
                    tool_call_result.tool_call_id.clone(),
                    RedactedToolKind::default(),
                    ToolResultSource::PersistedHistory,
                    persisted_tool_result_kind(msg, Some(compacted_tool_msg_ids)),
                ));
            }
            api::message::Message::ServerEvent(_)
            | api::message::Message::SystemQuery(_)
            | api::message::Message::UpdateTodos(_)
            | api::message::Message::Summarization(_)
            | api::message::Message::CodeReview(_)
            | api::message::Message::UpdateReviewComments(_)
            | api::message::Message::WebSearch(_)
            | api::message::Message::WebFetch(_)
            | api::message::Message::DebugOutput(_)
            | api::message::Message::ArtifactEvent(_)
            | api::message::Message::InvokeSkill(_)
            | api::message::Message::MessagesReceivedFromAgents(_)
            | api::message::Message::ModelUsed(_)
            | api::message::Message::EventsFromAgents(_)
            | api::message::Message::PassiveSuggestionResult(_) => {}
        }
    }

    let current_task_id = current_input_task_id(params);
    for (idx, input) in params.input.iter().enumerate() {
        match input {
            AIAgentInput::UserQuery { .. }
            | AIAgentInput::InvokeSkill { .. }
            | AIAgentInput::ResumeConversation { .. }
            | AIAgentInput::SummarizeConversation { .. } => {
                builder.push_user_boundary(
                    current_task_id.clone(),
                    format!("current_input:{idx}:user"),
                );
            }
            AIAgentInput::ActionResult { result, .. } => {
                let tool_call_id = result.id.to_string();
                let owner = builder.owner_of(&result.task_id.to_string(), &tool_call_id);
                builder.push_tool_result(ProjectedToolResult::new(
                    result.task_id.to_string(),
                    format!("current_input:{idx}:{tool_call_id}"),
                    owner,
                    tool_call_id,
                    RedactedToolKind::default(),
                    ToolResultSource::CurrentInput,
                    current_input_result_kind(result),
                ));
            }
            AIAgentInput::AutoCodeDiffQuery { .. }
            | AIAgentInput::InitProjectRules { .. }
            | AIAgentInput::TriggerPassiveSuggestion { .. }
            | AIAgentInput::CreateNewProject { .. }
            | AIAgentInput::CloneRepository { .. }
            | AIAgentInput::CodeReview { .. }
            | AIAgentInput::FetchReviewComments { .. }
            | AIAgentInput::StartFromAmbientRunPrompt { .. }
            | AIAgentInput::MessagesReceivedFromAgents { .. }
            | AIAgentInput::EventsFromAgents { .. }
            | AIAgentInput::PassiveSuggestionResult { .. } => {}
        }
    }

    builder.finish()
}

pub(crate) fn classify_byop_controller_readiness(params: &RequestParams) -> ReadinessReport {
    classify_byop_controller_readiness_with_live_tool_calls(params, Vec::new())
}

pub(crate) fn classify_byop_controller_readiness_with_live_tool_calls(
    params: &RequestParams,
    live_tool_calls: Vec<LiveToolCall>,
) -> ReadinessReport {
    let skipped_cancellation_results = current_input_cancellation_result_keys(params);
    let projection = build_controller_readiness_projection(params, &skipped_cancellation_results);
    let mut live_tool_calls_for_context =
        cancellation_live_tool_calls(params, &skipped_cancellation_results);
    live_tool_calls_for_context.extend(live_tool_calls);
    let context = ReadinessContext {
        repair_records: params.byop_repair_state.repair_records().to_vec(),
        live_tool_calls: live_tool_calls_for_context,
    };
    classify_projection(&projection, &context)
}

fn current_input_cancellation_result_keys(params: &RequestParams) -> HashSet<(String, String)> {
    params
        .input
        .iter()
        .filter_map(|input| {
            let AIAgentInput::ActionResult { result, .. } = input else {
                return None;
            };
            result
                .result
                .is_cancelled()
                .then(|| (result.task_id.to_string(), result.id.to_string()))
        })
        .collect()
}

fn cancellation_live_tool_calls(
    params: &RequestParams,
    skipped_cancellation_results: &HashSet<(String, String)>,
) -> Vec<LiveToolCall> {
    use crate::ai::agent::task::helper::ToolCallExt;

    params
        .tasks
        .iter()
        .flat_map(|task| task.messages.iter())
        .filter_map(|msg| {
            let api::message::Message::ToolCall(tool_call) = msg.message.as_ref()? else {
                return None;
            };
            if tool_call.subagent().is_some() {
                return None;
            }
            if !skipped_cancellation_results
                .contains(&(msg.task_id.clone(), tool_call.tool_call_id.clone()))
            {
                return None;
            }
            Some(LiveToolCall::new(
                ToolCallRef::new(
                    ToolCallKey::new(&msg.task_id, &msg.id, &tool_call.tool_call_id),
                    redacted_tool_kind_for_tool_call(tool_call),
                ),
                LiveToolCallState::CancellationRequested,
            ))
        })
        .collect()
}

fn build_controller_readiness_projection(
    params: &RequestParams,
    skipped_current_action_results: &HashSet<(String, String)>,
) -> Vec<ProjectionItem> {
    let mut builder = SerializerProjectionBuilder::new();

    for msg in params.tasks.iter().flat_map(|task| task.messages.iter()) {
        let Some(inner) = &msg.message else {
            continue;
        };

        match inner {
            api::message::Message::UserQuery(_) => {
                builder.push_user_boundary(msg.task_id.clone(), msg.id.clone());
            }
            api::message::Message::AgentOutput(_) => {
                builder.push_assistant_boundary(msg.task_id.clone(), msg.id.clone());
            }
            api::message::Message::AgentReasoning(_) => {}
            api::message::Message::ToolCall(tool_call) => {
                builder.push_tool_call(&msg.task_id, &msg.id, tool_call);
            }
            api::message::Message::ToolCallResult(tool_call_result) => {
                if builder.should_skip_tool_result(&msg.task_id, &tool_call_result.tool_call_id) {
                    continue;
                }
                let owner = builder.owner_of(&msg.task_id, &tool_call_result.tool_call_id);
                builder.push_tool_result(ProjectedToolResult::new(
                    msg.task_id.clone(),
                    msg.id.clone(),
                    owner,
                    tool_call_result.tool_call_id.clone(),
                    RedactedToolKind::default(),
                    ToolResultSource::PersistedHistory,
                    persisted_tool_result_kind(msg, None),
                ));
            }
            api::message::Message::ServerEvent(_)
            | api::message::Message::SystemQuery(_)
            | api::message::Message::UpdateTodos(_)
            | api::message::Message::Summarization(_)
            | api::message::Message::CodeReview(_)
            | api::message::Message::UpdateReviewComments(_)
            | api::message::Message::WebSearch(_)
            | api::message::Message::WebFetch(_)
            | api::message::Message::DebugOutput(_)
            | api::message::Message::ArtifactEvent(_)
            | api::message::Message::InvokeSkill(_)
            | api::message::Message::MessagesReceivedFromAgents(_)
            | api::message::Message::ModelUsed(_)
            | api::message::Message::EventsFromAgents(_)
            | api::message::Message::PassiveSuggestionResult(_) => {}
        }
    }

    let current_task_id = current_input_task_id(params);
    for (idx, input) in params.input.iter().enumerate() {
        match input {
            AIAgentInput::UserQuery { .. }
            | AIAgentInput::InvokeSkill { .. }
            | AIAgentInput::ResumeConversation { .. }
            | AIAgentInput::SummarizeConversation { .. } => {
                builder.push_user_boundary(
                    current_task_id.clone(),
                    format!("current_input:{idx}:user"),
                );
            }
            AIAgentInput::ActionResult { result, .. } => {
                let tool_call_id = result.id.to_string();
                if skipped_current_action_results
                    .contains(&(result.task_id.to_string(), tool_call_id.clone()))
                {
                    continue;
                }
                let owner = builder.owner_of(&result.task_id.to_string(), &tool_call_id);
                builder.push_tool_result(ProjectedToolResult::new(
                    result.task_id.to_string(),
                    format!("current_input:{idx}:{tool_call_id}"),
                    owner,
                    tool_call_id,
                    RedactedToolKind::default(),
                    ToolResultSource::CurrentInput,
                    current_input_result_kind(result),
                ));
            }
            AIAgentInput::AutoCodeDiffQuery { .. }
            | AIAgentInput::InitProjectRules { .. }
            | AIAgentInput::TriggerPassiveSuggestion { .. }
            | AIAgentInput::CreateNewProject { .. }
            | AIAgentInput::CloneRepository { .. }
            | AIAgentInput::CodeReview { .. }
            | AIAgentInput::FetchReviewComments { .. }
            | AIAgentInput::StartFromAmbientRunPrompt { .. }
            | AIAgentInput::MessagesReceivedFromAgents { .. }
            | AIAgentInput::EventsFromAgents { .. }
            | AIAgentInput::PassiveSuggestionResult { .. } => {}
        }
    }

    builder.finish()
}

fn validate_byop_serializer_readiness(
    params: &RequestParams,
    all_msgs: &[&api::Message],
    summarize_head_end: Option<usize>,
    summary_inserts: &HashMap<String, String>,
    hidden_msg_ids: &std::collections::HashSet<String>,
    compacted_tool_msg_ids: &std::collections::HashSet<String>,
) -> Result<ReadinessReport, ConvertToAPITypeError> {
    let projection = build_serializer_readiness_projection(
        params,
        all_msgs,
        summarize_head_end,
        summary_inserts,
        hidden_msg_ids,
        compacted_tool_msg_ids,
    );
    let conversation_id = params
        .byop_conversation_id
        .map(|id| id.to_string())
        .unwrap_or_else(|| "unknown".to_owned());
    let request_attempt_id = params
        .byop_readiness_attempt_id
        .clone()
        .unwrap_or_else(|| "serializer-unknown".to_owned());
    validate_serializer_readiness_projection_with_repair_state(
        projection,
        &params.byop_repair_state,
        &ReadinessDiagnosticContext::new(
            &conversation_id,
            &request_attempt_id,
            ReadinessTriggerLayer::SerializerValidation,
        ),
    )
}

fn validate_serializer_readiness_projection(
    projection: Vec<ProjectionItem>,
) -> Result<ReadinessReport, ConvertToAPITypeError> {
    validate_serializer_readiness_projection_with_repair_state(
        projection,
        &RepairStateStatus::default(),
        &ReadinessDiagnosticContext::new(
            "test-conversation",
            "test-attempt",
            ReadinessTriggerLayer::SerializerValidation,
        ),
    )
}

fn validate_serializer_readiness_projection_with_repair_state(
    projection: Vec<ProjectionItem>,
    repair_state: &RepairStateStatus,
    diagnostic_context: &ReadinessDiagnosticContext<'_>,
) -> Result<ReadinessReport, ConvertToAPITypeError> {
    let context = ReadinessContext {
        repair_records: repair_state.repair_records().to_vec(),
        live_tool_calls: Vec::new(),
    };
    let report = classify_projection(&projection, &context);

    match &report.state {
        ReadinessState::Ready => {
            if let Some(error_category) = repair_state.error_category() {
                log::error!(
                    "[byop-readiness] serializer continuing with invalid repair sidecar \
                     category={error_category:?} projection_items={}",
                    projection.len()
                );
            }
            Ok(report)
        }
        ReadinessState::AcceptedHistoryRepair { repairs } => {
            log_accepted_history_repair(repairs, diagnostic_context);
            Ok(report)
        }
        ReadinessState::PendingToolResults { .. }
        | ReadinessState::NeedsCancellationCommit { .. }
        | ReadinessState::DuplicateToolResults { .. }
        | ReadinessState::OrphanToolResult { .. }
        | ReadinessState::OutOfOrderToolResult { .. }
        | ReadinessState::MissingResultWithoutRepairSource { .. } => {
            let category = report.state.category();
            let mut diagnostics = ReadinessDiagnosticCoalescer::default();
            diagnostics.log_state(
                &report.state,
                diagnostic_context,
                ReadinessDiagnosticLevel::Error,
            );
            diagnostics.finish(diagnostic_context, ReadinessDiagnosticLevel::Error);
            log::error!(
                "[byop-readiness] serializer blocked request category={category:?} \
                 projection_items={} ignored_repair_records={} trigger_layer=serializer_validation \
                 request_attempt_id={}",
                projection.len(),
                report.ignored_repair_records.len(),
                diagnostic_context.request_attempt_id
            );

            Err(ConvertToAPITypeError::Other(
                BlockedByopReadinessError::new(category).into(),
            ))
        }
    }
}

fn log_accepted_history_repair(
    repairs: &[AcceptedRepair],
    diagnostic_context: &ReadinessDiagnosticContext<'_>,
) {
    log::info!(
        "{}",
        accepted_history_repair_log_message(repairs, diagnostic_context)
    );
}

fn accepted_history_repair_log_message(
    repairs: &[AcceptedRepair],
    diagnostic_context: &ReadinessDiagnosticContext<'_>,
) -> String {
    let forked_history_count = repairs
        .iter()
        .filter(|repair| matches!(repair.record.source, RepairSource::ForkedHistory))
        .count();
    let restored_legacy_history_count = repairs
        .iter()
        .filter(|repair| matches!(repair.record.source, RepairSource::RestoredLegacyHistory))
        .count();

    format!(
        "[byop-readiness] serializer accepted history repair records={} \
         category={:?} forked_history={} restored_legacy_history={} conversation_id={} \
         trigger_layer=serializer_validation request_attempt_id={} repair_keys={:?}",
        repairs.len(),
        ReadinessCategory::AcceptedHistoryRepair,
        forked_history_count,
        restored_legacy_history_count,
        diagnostic_context.conversation_id,
        diagnostic_context.request_attempt_id,
        repairs
            .iter()
            .map(|repair| format!(
                "task_id={} assistant_tool_call_message_id={} tool_call_id={} redacted_tool_kind={}",
                repair.tool_call.key.task_id,
                repair.tool_call.key.assistant_tool_call_message_id,
                repair.tool_call.key.tool_call_id,
                repair.tool_call.redacted_tool_kind.as_str()
            ))
            .collect::<Vec<_>>()
    )
}

/// Translates RequestParams into a genai `ChatRequest` (including system + messages +
/// tools).
///
/// `force_echo_reasoning`: decided by `super::reasoning::model_requires_reasoning_echo`.
/// When true, every assistant message is forced to carry reasoning_content (empty-string
/// placeholder), fixing thinking-mode endpoints with tightened validation such as
/// DeepSeek-v4-flash / Kimi.
fn build_chat_request(
    params: &RequestParams,
    force_echo_reasoning: bool,
    api_type: AgentProviderApiType,
    attachment_caps: attachment_caps::AttachmentCaps,
) -> Result<ChatRequest, ConvertToAPITypeError> {
    // When input has a non-empty context: use it directly, and remember it as a fallback
    // for later no-input requests in this conversation.
    // When input is empty (tool result / auto-resume): fall back to the last value
    // remembered for this conversation, to avoid the <env> section degrading to default
    // values and breaking the prompt cache.
    let input_ctx = latest_input_context(&params.input);
    let fallback_ctx: Option<Vec<AIAgentContext>> = if input_ctx.is_empty() {
        params.byop_conversation_id.and_then(|id| {
            CONVERSATION_SYSTEM_CTX
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .as_ref()
                .filter(|(cached_id, _)| *cached_id == id)
                .map(|(_, ctx)| ctx.clone())
        })
    } else {
        if let Some(id) = params.byop_conversation_id {
            *CONVERSATION_SYSTEM_CTX
                .lock()
                .unwrap_or_else(|p| p.into_inner()) = Some((id, input_ctx.to_vec()));
        }
        None
    };
    let agent_ctx: &[AIAgentContext] = fallback_ctx.as_deref().unwrap_or(input_ctx);
    log::info!(
        "[byop-diag] system_ctx inputs={} ctx_len={} used_fallback={} has_directory={} has_exec_env={}",
        params.input.len(),
        agent_ctx.len(),
        fallback_ctx.is_some(),
        agent_ctx
            .iter()
            .any(|c| matches!(c, AIAgentContext::Directory { .. })),
        agent_ctx
            .iter()
            .any(|c| matches!(c, AIAgentContext::ExecutionEnvironment(_))),
    );
    let plan_mode = is_plan_mode_turn(&params.input);
    let tool_names = available_tool_names(params);
    // The `# Available Tools` text list (tool_aliases.j2, driven by this slice) is
    // redundant with the structured `tools` array we send via `with_tools`:
    // `build_tools_array` and `available_tool_names` share the exact same gating,
    // so a non-empty name list means the native tools array is also going out.
    // Pass an empty slice in that case to suppress the duplicate text block and
    // save prompt tokens; only surface the text list if we are NOT sending
    // structured tools (no such path today, but keeps the behavior principled).
    let prompt_tool_names: &[String] = if tool_names.is_empty() {
        &tool_names
    } else {
        &[]
    };
    let mut system_text = prompt_renderer::render_system_with_override(
        api_type,
        &params.model,
        agent_ctx,
        prompt_tool_names,
        plan_mode,
        &params.user_rules,
        params.prompt_override.as_ref(),
    );
    // Zap: legacy SSH session profile patch. `render_system` goes through AIAgentContext,
    // which reports the local client's OS/shell; under legacy SSH the PTY actually runs on
    // the remote host, so we append an SSH status block to correct the LLM's inference.
    if let Some(ssh_block) = render_ssh_session_block(&params.session_context) {
        system_text.push_str(&ssh_block);
    }
    // Note: LRC / long-running-command tool-usage guidance (write_to_long_running_shell_command
    // + command_id + the various modes and raw byte sequences) is already fully covered in
    // `prompts/system/default.j2:69-79`. The user's current concrete PTY context (command
    // name / alt-screen flag / grid contents) is injected separately via the
    // `<attached_running_command>` XML block prefixed onto the user message (see
    // `render_running_command_context` and the UserQuery branch in build_chat_request).
    // We don't duplicate hardcoding things like TUI exit keys at this system-prompt layer,
    // to avoid conflicting with or being redundant with default.j2's standard guidance.

    let mut messages: Vec<ChatMessage> = Vec::new();
    let mut outbound_tool_groups: Vec<OutboundAssistantToolGroup> = Vec::new();

    // Collect messages from all tasks, running them through
    // `collect_linearized_task_messages` for deterministic DFS linearization + UserQuery
    // dedup (fixes Issue #94 — historical-turn user messages getting sorted out of order to
    // the end, or duplication from LRC subagent copies). See that function's doc comment for
    // details.
    let all_msgs: Vec<&api::Message> = collect_linearized_task_messages(&params.tasks);

    // Zap BYOP local conversation compaction: applies conversation.compaction_state to the
    // message sequence.
    //   1. Filters out (user, assistant) pairs already superseded by a compaction
    //      (`hidden_message_ids`)
    //   2. Inserts a synthetic (user "compacted, summary follows" + assistant summary text)
    //      message pair at the position of the hidden range — this step is emitted inline in
    //      the main loop via the `summary_inserts` index
    //   3. When a ToolCallResult's marker.tool_output_compacted_at is non-empty, a later
    //      branch replaces the content with a placeholder
    //
    // When the current input is `AIAgentInput::SummarizeConversation`: additionally use the
    // select algorithm to cut messages down to the head (dropping the tail), and at the end
    // of the input loop append `build_prompt(...)` as a user message (going through the full
    // SUMMARY_TEMPLATE) so the upstream LLM outputs a structured summary.
    let is_summarization_request = params
        .input
        .iter()
        .any(|i| matches!(i, AIAgentInput::SummarizeConversation { .. }));
    let summarization_overflow = params.input.iter().any(|i| {
        matches!(
            i,
            AIAgentInput::SummarizeConversation { overflow: true, .. }
        )
    });
    let _ = summarization_overflow; // Used by the follow-up wording branch inside the input loop; silencing dead-code for now

    let summary_inserts: std::collections::HashMap<String, String> =
        if let Some(state) = params.compaction_state.as_ref() {
            // user_msg_id → summary_text; when this user_msg_id is encountered (it would
            // otherwise be hidden), replace it with the synthetic summary pair
            state
                .completed()
                .iter()
                .filter_map(|c| {
                    c.summary_text
                        .as_ref()
                        .map(|s| (c.user_msg_id.clone(), s.clone()))
                })
                .collect()
        } else {
            std::collections::HashMap::new()
        };
    let hidden_msg_ids: std::collections::HashSet<String> = params
        .compaction_state
        .as_ref()
        .map(|s| s.hidden_message_ids())
        .unwrap_or_default();
    let compacted_tool_msg_ids: std::collections::HashSet<String> = params
        .compaction_state
        .as_ref()
        .map(|s| {
            // Collects the message_ids of all ToolCallResults marked with
            // tool_output_compacted_at, implemented by iterating all_msgs and checking the
            // marker
            let mut out = std::collections::HashSet::new();
            for msg in &all_msgs {
                if let Some(api::message::Message::ToolCallResult(_)) = &msg.message {
                    if s.marker(&msg.id)
                        .and_then(|m| m.tool_output_compacted_at)
                        .is_some()
                    {
                        out.insert(msg.id.clone());
                    }
                }
            }
            out
        })
        .unwrap_or_default();

    // Summarization-request path: use byop_compaction::algorithm::select to cut the head;
    // the tail is not sent upstream
    let summarize_head_end: Option<usize> = if is_summarization_request {
        // Temporarily project into WarpMessageView to compute select
        let state_for_select = params.compaction_state.clone().unwrap_or_default();
        let tool_names =
            byop_compaction::message_view::build_tool_name_lookup(all_msgs.iter().copied());
        let views =
            byop_compaction::message_view::project(&all_msgs, &state_for_select, &tool_names);
        let cfg = byop_compaction::CompactionConfig::default();
        let model_limit = byop_compaction::overflow::ModelLimit::FALLBACK;
        let result = byop_compaction::algorithm::select(&views, &cfg, model_limit, |slice| {
            slice
                .iter()
                .map(byop_compaction::algorithm::MessageRef::estimate_size)
                .sum()
        });
        // head_end is the upper bound of the "head range" within views, in the same order
        // as all_msgs
        Some(result.head_end)
    } else {
        None
    };

    let readiness_report = validate_byop_serializer_readiness(
        params,
        &all_msgs,
        summarize_head_end,
        &summary_inserts,
        &hidden_msg_ids,
        &compacted_tool_msg_ids,
    )?;

    let mut buf = AssistantBuffer::new(force_echo_reasoning);
    // Zap: call_ids of subagent ToolCalls that were skipped in history — their
    // ToolCallResults must also be skipped, or they become orphan tool_responses and
    // Anthropic flatly 400s with `unexpected tool_use_id ... no corresponding tool_use block`.
    let mut skipped_subagent_call_ids: std::collections::HashSet<String> =
        std::collections::HashSet::new();
    // Zap: only allow stripping suspected tool JSON out of AgentOutput when "a structured
    // ToolCall actually landed under this same task_id" — avoids using evidence from the
    // whole history range to mistakenly damage a plain-text answer from a different turn
    // (different task_id).
    let tasks_with_tool_call: std::collections::HashSet<&str> = all_msgs
        .iter()
        .filter(|msg| matches!(msg.message, Some(api::message::Message::ToolCall(_))))
        .map(|msg| msg.task_id.as_str())
        .collect();

    for (idx, msg) in all_msgs.iter().enumerate() {
        // Summarization request: the tail range isn't sent upstream (only head + appending
        // SUMMARY_TEMPLATE at the end)
        if let Some(head_end) = summarize_head_end {
            if idx >= head_end {
                continue;
            }
        }
        if hidden_msg_ids.contains(&msg.id) {
            if let Some(summary_text) = summary_inserts.get(&msg.id) {
                flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);
                messages.push(ChatMessage::user(
                    "Conversation history was compacted. Below is the structured summary of all prior turns.".to_string(),
                ));
                messages.push(ChatMessage::assistant(summary_text.clone()));
            }
            continue;
        }
        let Some(inner) = &msg.message else {
            continue;
        };
        match inner {
            api::message::Message::UserQuery(u) => {
                flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);
                // Zap: keeps historical-turn multimodal content alive. Warp's own path relies
                // on the cloud server to re-inject InputContext; the BYOP direct path doesn't
                // have that layer, so `make_user_query_message` stuffs all binaries (image /
                // pdf / audio) into `UserQuery.context.images` when persisting. Here we
                // reverse that back into UserBinary via `build_user_message_with_binaries`, so
                // later turns' model can still see multimodal attachments pasted earlier.
                // mimes unsupported by the model's caps get replaced with ERROR text by
                // `build_user_message_with_binaries` (opencode unsupportedParts style),
                // never silently dropped.
                // No binaries → fall back to the old path, `ChatMessage::user(text)`,
                // equivalent to pre-fix behavior.
                let history_binaries: Vec<user_context::UserBinary> = u
                    .context
                    .as_ref()
                    .map(|ctx| {
                        ctx.images
                            .iter()
                            .filter(|b| !b.data.is_empty())
                            .enumerate()
                            .map(|(idx, b)| {
                                use base64::Engine;
                                user_context::UserBinary {
                                    name: format!("history-attachment-{}-{idx}", &msg.id),
                                    content_type: if b.mime_type.is_empty() {
                                        "application/octet-stream".to_string()
                                    } else {
                                        b.mime_type.clone()
                                    },
                                    data: base64::engine::general_purpose::STANDARD.encode(&b.data),
                                }
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let mut history_prefixes: Vec<String> = Vec::new();
                // Reconstructs `<attached_context>` on replay (the auto-attached block of
                // already-executed commands).
                //
                // These blocks were rendered as a user message prefix from the live context
                // by `collect_user_attachments` on the turn they were sent; if not
                // reconstructed on replay, the same message shrinks from "long text with
                // attached_context" down to a "bare query" — isomorphic to the <env> bug
                // above, just further downstream.
                //
                // WARNING: but the block below is currently **mostly a no-op** — don't be
                // fooled by it:
                // `make_user_query_message` only stuffs binaries into `InputContext` when
                // persisting (see `let context = if proto_binaries.is_empty() { None } else
                // {...}` in this file) — Directory / Git / CurrentTime / Block are never
                // written at all. `convert_context` (`convert_to.rs:673`) does serialize
                // them, but it's only called on the **request** path, never used to build
                // the persisted message. So `convert_input_context` can in practice only
                // ever recover `[Image, ...]`, meaning the prefix here is at most an image
                // block.
                //
                // This code is kept because it's correct in itself: whenever
                // `make_user_query_message` actually persists the full context (see the
                // plan's follow-up), it will kick in automatically with no further changes
                // needed.
                //
                // The order must match the live path (attachments first, then referenced),
                // or the assembled text still won't match.
                let history_ctx = crate::ai::agent::api::convert_conversation::convert_input_context(
                    u.context.as_ref(),
                );
                if let Some(prefix) = user_context::collect_user_attachments(&history_ctx).prefix {
                    history_prefixes.push(prefix);
                }
                if let Some(prefix) =
                    user_context::render_api_referenced_attachments(&u.referenced_attachments)
                {
                    history_prefixes.push(prefix);
                }
                let history_text = if history_prefixes.is_empty() {
                    u.query.clone()
                } else {
                    format!("{}\n\n{}", history_prefixes.join("\n\n"), u.query)
                };
                if history_binaries.is_empty() {
                    messages.push(ChatMessage::user(history_text));
                } else {
                    messages.push(build_user_message_with_binaries(
                        history_text,
                        history_binaries,
                        attachment_caps,
                    ));
                }
            }
            api::message::Message::AgentReasoning(r) => {
                // Attaches the previous turn's reasoning to the next assistant message that
                // gets flushed. genai 0.6's with_reasoning_content serializes per the current
                // adapter: DeepSeek/Kimi → reasoning_content field; Anthropic → thinking
                // blocks. Multiple AgentReasoning segments accumulate (the same turn may
                // stream out multiple reasoning chunks that land as multiple AgentReasoning
                // entries).
                let next = r.reasoning.clone();
                if !next.is_empty() {
                    match buf.reasoning.as_mut() {
                        Some(existing) => existing.push_str(&next),
                        None => buf.reasoning = Some(next),
                    }
                }
            }
            api::message::Message::AgentOutput(a) => {
                // Ollama local models often land tool JSON as AgentOutput text; the same
                // turn also has a structured ToolCall + ToolCallResult later on. Sending it
                // upstream too would drown out the real summary, causing C3 amnesia. Only
                // strip it when (a) a structured ToolCall has already landed under the same
                // task_id, and (b) this text itself yields an executable call when run
                // through extract_tool_calls_from_assistant_text — `contains_tool_shaped_json`
                // returns true as soon as a string `name` key appears (e.g. pasted
                // package.json content), which would mistake a legitimate answer for tool
                // JSON noise and delete it.
                if api_type == AgentProviderApiType::Ollama
                    && tasks_with_tool_call.contains(msg.task_id.as_str())
                    && !super::content_tool_calls::extract_tool_calls_from_assistant_text(
                        &a.text,
                        &tool_names,
                    )
                    .is_empty()
                {
                    continue;
                }
                if buf.text.is_some() || !buf.tool_calls.is_empty() {
                    flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);
                }
                buf.text = Some(a.text.clone());
            }
            api::message::Message::ToolCall(tc) => {
                // Zap BYOP: **virtual subagent tool_calls are not sent to the upstream
                // model**. In the LRC tag-in scenario, we synthesize a
                // `Tool::Subagent { metadata: Cli }` at the head of the chat_stream and write
                // it into root.task.messages, purely to trigger the conversation into
                // creating a cli subtask + spawning the floating window — it's not a tool
                // call the model actually produced, and the model would be confused seeing
                // it (an extra tool call it can't respond to). Its corresponding
                // ToolCallResult likewise needs to be filtered out by the branch below, to
                // avoid an imbalance where a "tool_response has no matching tool_call".
                use crate::ai::agent::task::helper::ToolCallExt;
                if tc.subagent().is_some() {
                    skipped_subagent_call_ids.insert(tc.tool_call_id.clone());
                    continue;
                }
                if buf
                    .tool_call_keys
                    .first()
                    .is_some_and(|key| key.task_id != msg.task_id)
                {
                    flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);
                }
                let (name, args_json) = serialize_outgoing_tool_call(
                    tc,
                    params.mcp_context.as_ref(),
                    &msg.server_message_data,
                );
                let assistant_message_id = buf
                    .tool_call_keys
                    .first()
                    .map(|key| key.assistant_tool_call_message_id.clone())
                    .unwrap_or_else(|| msg.id.clone());
                let key = ToolCallKey::new(&msg.task_id, assistant_message_id, &tc.tool_call_id);
                buf.push_tool_call(
                    ToolCall {
                        call_id: tc.tool_call_id.clone(),
                        fn_name: name,
                        fn_arguments: args_json,
                        thought_signatures: None,
                    },
                    key,
                );
            }
            api::message::Message::ToolCallResult(tcr) => {
                flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);
                // Zap: the corresponding ToolCall was already skipped (subagent virtual
                // call) → the result is skipped too, otherwise it leaves an orphan
                // tool_response and the upstream 400s.
                if skipped_subagent_call_ids.contains(&tcr.tool_call_id) {
                    continue;
                }
                // BYOP-persisted ToolCallResults use server_message_data (content is
                // already a JSON string); server-side emit uses the structured result oneof
                // variant — support both paths.
                let content = if compacted_tool_msg_ids.contains(&msg.id) {
                    // Compaction projection: pruned tool output is replaced with a
                    // placeholder, the real content isn't sent upstream
                    r#"{"status":"compacted","note":"tool output was pruned by local compaction"}"#
                        .to_string()
                } else if tcr.result.is_some() {
                    tools::serialize_result(tcr)
                } else if !msg.server_message_data.is_empty() {
                    msg.server_message_data.clone()
                } else {
                    r#"{"status":"empty"}"#.to_owned()
                };
                messages.push(ChatMessage::from(ToolResponse::new(
                    tcr.tool_call_id.clone(),
                    cap_tool_response_content(content),
                )));
            }
            _ => {
                // Other message types (SystemQuery/UpdateTodos/...) aren't sent upstream by
                // BYOP for now.
            }
        }
    }
    flush_assistant_buffer(&mut buf, &mut messages, &mut outbound_tool_groups);

    // Current turn's new input → append it.
    for input in &params.input {
        match input {
            AIAgentInput::UserQuery {
                query,
                context,
                referenced_attachments,
                running_command,
                ..
            } => {
                // The attachment-type context (Block / SelectedText / File / Image) that
                // comes with the current turn's UserQuery strictly aligns with the semantics
                // of warp's own path, which goes through fields like
                // `api::InputContext.executed_shell_commands` and has the backend inject them
                // into the prompt after upload. BYOP has no such backend layer, so we prepend
                // directly to the user message. Environment-type context (env / git / skills
                // / ...) is rendered into the system prompt by prompt_renderer, and doesn't
                // overlap with this path.
                //
                // Zap: in the LRC tag-in scenario, `running_command: Some(...)` carries the
                // full PTY context (alt-screen grid_contents + command + is_alt_screen_active
                // flag), rendered via `render_running_command_context` into an
                // `<attached_running_command>` XML block. The model uses this to decide
                // whether to call write_to_long_running_shell_command. When it's not filled
                // in (a normal conversation, or the controller didn't inject it), we fall
                // back to the short `lrc_command_id` context.
                //
                // **P1-10 prompt cache optimization**: the LRC context block is **appended
                // after the query** rather than prefixed. Reasons:
                //   - grid_contents changes every second along with PTY state — it's
                //     "high-churn" content.
                //   - Putting it before the query would make the head of the user message
                //     unstable → the hash written by the 2 Anthropic breakpoints at the end
                //     of the messages section would always differ, giving low reuse value.
                //   - Putting it after the query means the same query (e.g. "exit nvim")
                //     still shares the "user question" prefix across different PTY
                //     snapshots, improving cross-call reuse potential.
                // The difference in model behavior is negligible: whether the instruction or
                // the context comes first, the model understands it correctly either way.
                // user_attachments' prefix (e.g. SelectedText / Block) still goes in the
                // prefix position, because it corresponds to content the user "explicitly
                // selected" and should serve as the question's background rather than a
                // supplementary instance.
                // LRC (long-running command) context has been moved to a temporary block at
                // the end of the message list, and is no longer a suffix on the user message.
                // See the comment above `push_environment_context_message` for why:
                //
                // `grid_contents` is a PTY snapshot that changes every second, and the user
                // message it's attached to **does not** get persisted together with the LRC
                // data (on replay, `convert_conversation.rs` gives `running_command: None`,
                // and the persisted message proto has no such field at all). So the same
                // message carries the LRC snapshot "the turn it's sent" but reverts to a bare
                // query "on replay" — the content drifts turn to turn, and the cache keyed on
                // that message misses. This is the same bug as <env>, just a different field.
                //
                // It's inherently "the current environment state", same category as cwd, so
                // it should be regenerated fresh every turn and placed at the end.
                let suffixes: Vec<String> = Vec::new();
                let mut prefixes: Vec<String> = Vec::new();
                let user_attachments = user_context::collect_user_attachments(context);
                if let Some(p) = &user_attachments.prefix {
                    prefixes.push(p.clone());
                }
                if let Some(p) = user_context::render_referenced_attachments(referenced_attachments)
                {
                    prefixes.push(p);
                }
                let full_text = match (prefixes.is_empty(), suffixes.is_empty()) {
                    (true, true) => query.clone(),
                    (false, true) => format!("{}\n\n{query}", prefixes.join("\n\n")),
                    (true, false) => format!("{query}\n\n{}", suffixes.join("\n\n")),
                    (false, false) => format!(
                        "{}\n\n{query}\n\n{}",
                        prefixes.join("\n\n"),
                        suffixes.join("\n\n"),
                    ),
                };
                log::info!(
                    // running_command is now only an observational value for "did this
                    // turn's input carry LRC or not" — its content no longer goes into this
                    // message (that's now carried by the environment_context block at the
                    // end instead).
                    "[byop-diag] build_chat_request UserQuery: query_len={} \
                     running_command={}(→tail) prefixes={} suffixes={} full_text_len={} binaries={}",
                    query.len(),
                    match running_command.as_ref() {
                        Some(rc) => format!(
                            "Some(grid_len={} alt={})",
                            rc.grid_contents.len(),
                            rc.is_alt_screen_active
                        ),
                        None => "None".to_owned(),
                    },
                    prefixes.len(),
                    suffixes.len(),
                    full_text.len(),
                    user_attachments.binaries.len(),
                );
                messages.push(build_user_message_with_binaries(
                    full_text,
                    user_attachments.binaries,
                    attachment_caps,
                ));
            }
            AIAgentInput::ActionResult { result, .. } => {
                // The previous turn's model returned tool_calls; after the client executes
                // them, the result goes through `params.input` rather than the
                // `params.tasks` history. It must be serialized to a ToolResponse here, or
                // genai/upstream will 400 due to a tool_call_id pairing failure.
                let tool_call_id = result.id.to_string();
                let content = tools::serialize_action_result(result).unwrap_or_else(|| {
                    serde_json::json!({ "result": result.result.to_string() }).to_string()
                });
                messages.push(ChatMessage::from(ToolResponse::new(
                    tool_call_id,
                    cap_tool_response_content(content),
                )));
            }
            AIAgentInput::InvokeSkill {
                skill, user_query, ..
            } => {
                let mut composed = format!(
                    "Execute the task following the skill \"{}\" guide below:\n\n{}\n\n---\n",
                    skill.name, skill.content,
                );
                if let Some(uq) = user_query {
                    composed.push_str(&format!("Additional instruction from the user: {}", uq.query));
                }
                messages.push(ChatMessage::user(composed));
            }
            AIAgentInput::ResumeConversation { context } => {
                // BYOP has no server-side resume-prompt injection layer. On LRC auto-resume
                // we must explicitly re-carry the current PTY context, or the error-recovery
                // turn degrades into a normal conversation and re-picks a shell tool.
                let mut prefixes: Vec<String> = Vec::new();
                if let Some(lrc_prefix) = render_lrc_request_context(params) {
                    prefixes.push(lrc_prefix);
                }
                let user_attachments = user_context::collect_user_attachments(context);
                if let Some(p) = &user_attachments.prefix {
                    prefixes.push(p.clone());
                }
                if !prefixes.is_empty() {
                    let full_text = format!("{}\n\nContinue.", prefixes.join("\n\n"));
                    messages.push(build_user_message_with_binaries(
                        full_text,
                        user_attachments.binaries,
                        attachment_caps,
                    ));
                }
            }
            AIAgentInput::SummarizeConversation {
                prompt,
                overflow: _,
            } => {
                // Zap BYOP local conversation-compaction entry point — a 1:1 port of
                // opencode's `compaction.ts processCompaction`.
                //
                // The messages loop earlier already cut the sequence down to the head
                // (dropping the tail) based on `summarize_head_end`; here we append one
                // final user message: `build_prompt(previous_summary, plugin_context)`,
                // which includes the SUMMARY_TEMPLATE (a 9-section Markdown template) + an
                // incremental-summary anchor.
                //
                // The model emits a structured Markdown summary; once the controller
                // receives the stream's completion it writes it back into
                // conversation.compaction_state (see the Phase 6 controller changes).
                let prev_summary = params
                    .compaction_state
                    .as_ref()
                    .and_then(|s| s.previous_summary())
                    .map(str::to_string);
                let mut anchor_context: Vec<String> = Vec::new();
                if let Some(custom) = prompt.as_ref().filter(|p| !p.is_empty()) {
                    // /compact <custom instructions> goes here — appends the user's
                    // instructions to the plugin_context section
                    anchor_context
                        .push(format!("Additional instructions from the user:\n{custom}"));
                }
                let nextp =
                    byop_compaction::prompt::build_prompt(prev_summary.as_deref(), &anchor_context);
                messages.push(ChatMessage::user(nextp));
            }
            AIAgentInput::AutoCodeDiffQuery { .. }
            | AIAgentInput::CreateNewProject { .. }
            | AIAgentInput::CodeReview { .. } => {
                // Ignored for now
            }
            _ => {}
        }
    }

    if let ReadinessState::AcceptedHistoryRepair { repairs } = &readiness_report.state {
        repair_tool_call_pairs_for_accepted_history_gaps(
            &mut messages,
            repairs,
            &outbound_tool_groups,
        )?;
    }

    // `<environment_context>` tail block: cwd / git branch / date.
    //
    // These fields used to live in the system prompt's <env> section, where a single `cd`
    // would change message[0], and FLM's entry-by-entry comparison would mismatch right at
    // the first entry → a full re-prefill for the whole turn (observed ~10K tokens / 33s).
    // After moving them to the end, the system prompt is byte-for-byte constant, the first
    // point of divergence lands on the last message, and exactly the content newly added
    // this turn needs re-prefilling.
    //
    // Key point: we use `agent_ctx` here (not params.input), so turns where `params.input`
    // is empty — like tool result / auto-resume — still get environment state — which is
    // exactly the scenario where the agent most needs a correct cwd, right after `cd`-ing
    // itself inside a tool loop.
    //
    // Skipped on a Summarize turn: the compaction prompt must be the last message, or the
    // summary-format instructions get diluted.
    let is_summarize_turn = params
        .input
        .iter()
        .any(|i| matches!(i, AIAgentInput::SummarizeConversation { .. }));
    // Defensive sanitize: make sure messages doesn't end on an assistant message.
    // Anthropic / some gateways don't accept a request that ends on assistant (prefill is
    // only supported by certain models), and warp's `AIAgentInput::ResumeConversation`
    // (handoff/auto-resume after error, etc.) doesn't append a new user message, which would
    // leave the sequence ending on a historical assistant message.
    // Unified fallback here: if the end is an assistant message, append an implicit user
    // message to let the upstream continue.
    ensure_ends_with_user(&mut messages);

    if !is_summarize_turn {
        let mut tail_blocks: Vec<String> = Vec::new();
        if let Some(env_block) = user_context::render_environment_context(agent_ctx) {
            tail_blocks.push(env_block);
        }
        // The LRC snapshot is likewise "current environment state": PTY content changes
        // every second and can't be persisted along with a message, so we rebuild it at the
        // end every turn together with <env>, instead of attaching it to some user message.
        let tail_running_command = params
            .input
            .iter()
            .find_map(|i| match i {
                AIAgentInput::UserQuery {
                    running_command, ..
                } => running_command.as_ref(),
                _ => None,
            })
            .or(params.lrc_running_command.as_ref());
        if let Some(rc) = tail_running_command {
            tail_blocks.push(render_running_command_context(rc));
        } else if let Some(command_id) = params.lrc_command_id.as_deref() {
            tail_blocks.push(render_running_command_id_context(command_id));
        }

        if !tail_blocks.is_empty() {
            let tail = tail_blocks.join("\n\n");
            log::info!(
                "[byop-diag] env_tail: len={} blocks={} inputs={}",
                tail.len(),
                tail_blocks.len(),
                params.input.len(),
            );
            push_environment_context_message(&mut messages, tail);
        }
    }


    let mut tools_array = build_tools_array(params);

    // Anthropic path: tags the **last tool** in the tools array with a 1h cache_control
    // breakpoint, making the whole tools section a long-TTL static prefix (aligned with
    // Zed's `crates/anthropic/src/completion.rs::254-258`).
    //
    // Processing order is `tools → system → messages`; a long TTL must come before a short
    // TTL. On this path:
    // - tools tail 1h (here)
    // - system 1h (`apply_caching_anthropic` on the ChatRole::System message)
    // - messages tail 5m (`apply_caching_anthropic` on the last 2 non-system)
    //
    // The tools section changes the least within a session (only when toggling web_search /
    // plan_mode / LRC), so the hit rate is extremely high; the 1h write's 2x base cost is
    // amortized over many reuses, making it effectively near-zero — and this also blocks an
    // external reverse proxy injecting a 5m breakpoint on system from causing a
    // 1h-after-5m ordering error (letting this single tools-1h breakpoint own the entire
    // tools+system static prefix).
    if matches!(api_type, AgentProviderApiType::Anthropic) {
        if let Some(last_tool) = tools_array.last_mut() {
            last_tool.cache_control = Some(CacheControl::Ephemeral1h);
        }
    }

    // Outbound message text is passed straight through to `serde_json` for JSON escaping;
    // we no longer do aggressive character-level sanitizing (see zed's `into_anthropic` /
    // opencode's `provider/transform.ts` — neither of them flatten control characters or
    // replace `\` / `"` at the outbound layer). Anthropic / OpenAI / Gemini's official APIs
    // and mainstream BYOP reverse proxies all correctly handle the legal escapes produced
    // by `serde_json`.

    // Prompt caching (1:1 ported from opencode's `provider/transform.ts::applyCaching`):
    // - opencode picks the first 2 system messages + last 2 non-system messages, and
    //   uniformly tags them with multi-SDK-compatible markers like
    //   anthropic.cacheControl / openaiCompatible.cache_control / bedrock.cachePoint.
    //   Each AI SDK provider implementation reads the key relevant to it and automatically
    //   ignores irrelevant keys.
    // - We go through rust-genai, whose Anthropic adapter supports per-message
    //   `cache_control`; the OpenAI / OpenAiResp adapter only recognizes
    //   `ChatOptions`-level prompt_cache_key / cache_control; DeepSeek / Gemini / Ollama
    //   cache implicitly server-side and need no client opt-in.
    // - So we only tag "per-message" on the Anthropic path here: push the system text as a
    //   ChatRole::System message to the head of messages and tag it Ephemeral, then also tag
    //   the last two non-system messages Ephemeral (corresponding to opencode's
    //   system+last-2 pattern). The OpenAI family's `prompt_cache_key` / `cache_control` is
    //   set in `build_chat_options` (request-level), which is also a downstream fallback of
    //   the same set of opencode rules.
    let messages = if matches!(api_type, AgentProviderApiType::Anthropic) {
        let mut msgs: Vec<ChatMessage> = std::iter::once(ChatMessage::system(system_text.clone()))
            .chain(messages)
            .collect();
        apply_caching_anthropic(&mut msgs);
        msgs
    } else {
        messages
    };

    let mut req = ChatRequest::from_messages(messages);
    // On the Anthropic path, system has already been folded into messages as a
    // ChatRole::System message, so we no longer set `with_system` — this avoids the genai
    // Anthropic adapter's "the first system message can't carry cache_control" restriction
    // (see the comment in `adapter_impl.rs::into_anthropic_request_parts`).
    if !matches!(api_type, AgentProviderApiType::Anthropic) {
        req = req.with_system(system_text);
    }
    if !tools_array.is_empty() {
        req = req.with_tools(tools_array);
    }
    Ok(req)
}

const BYOP_DIAG_SNIPPET_CHARS: usize = 240;
const REPAIR_PLACEHOLDER_NOTE: &str =
    "tool result was unavailable in repaired conversation history";

fn is_placeholder_tool_response_content(content: &str) -> bool {
    // NOTE: this exact Chinese string is a legacy placeholder value that may still be
    // present in old persisted conversation history (backward-compat check against
    // previously stored content) — kept verbatim intentionally, not translated.
    if content == "(tool 执行结果未保留)" {
        return true;
    }

    // Cheap pre-filter: placeholder JSON always contains `"unavailable"` (see the structural
    // validation below). This function gets called for every ToolResponse in history on
    // every turn's request; doing a full serde parse for each one in a long conversation
    // would be pure waste. We only do the full parse once the substring hits; a false-positive
    // substring match just costs one extra parse and doesn't affect the result.
    if !content.contains("unavailable") {
        return false;
    }

    let Ok(Value::Object(object)) = serde_json::from_str::<Value>(content) else {
        return false;
    };

    object.len() == 3
        && object.get("status").and_then(Value::as_str) == Some("unavailable")
        && matches!(
            object.get("reason").and_then(Value::as_str),
            Some("forked_history_repair" | "restored_legacy_history_repair")
        )
        && object.get("note").and_then(Value::as_str) == Some(REPAIR_PLACEHOLDER_NOTE)
}

fn insert_preferred_tool_response(
    responses_by_call_id: &mut HashMap<String, ToolResponse>,
    response: &ToolResponse,
) {
    let should_replace = match responses_by_call_id.get(&response.call_id) {
        None => true,
        Some(existing) => should_replace_tool_response(existing, response),
    };
    if should_replace {
        responses_by_call_id.insert(response.call_id.clone(), response.clone());
    }
}

fn should_replace_tool_response(existing: &ToolResponse, candidate: &ToolResponse) -> bool {
    is_placeholder_tool_response_content(&existing.content)
        || !is_placeholder_tool_response_content(&candidate.content)
}

fn snippet_for_log(s: &str, max_chars: usize) -> String {
    use std::fmt::Write as _;

    let mut out = String::new();
    for (idx, ch) in s.chars().enumerate() {
        if idx >= max_chars {
            out.push_str("...");
            break;
        }
        match ch {
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => {
                let _ = write!(out, "\\u{{{:04x}}}", c as u32);
            }
            c => out.push(c),
        }
    }
    out
}

fn json_value_for_log(value: &Value) -> (usize, String) {
    let json = serde_json::to_string(value)
        .unwrap_or_else(|_| "<failed-to-serialize-json-value>".to_owned());
    (json.len(), snippet_for_log(&json, BYOP_DIAG_SNIPPET_CHARS))
}

fn binary_for_log(binary: &Binary) -> String {
    let name = binary
        .name
        .as_deref()
        .map(|n| snippet_for_log(n, 80))
        .unwrap_or_default();
    match &binary.source {
        BinarySource::Base64(data) => format!(
            "mime={} name={} source=base64 chars={}",
            binary.content_type,
            name,
            data.len()
        ),
        BinarySource::Url(url) => format!(
            "mime={} name={} source=url chars={} url={}",
            binary.content_type,
            name,
            url.len(),
            snippet_for_log(url, 120)
        ),
    }
}

fn log_chat_request_details(
    chat_req: &ChatRequest,
    model_id: &str,
    api_type: AgentProviderApiType,
    base_url: &str,
) {
    let system_in_head = matches!(api_type, AgentProviderApiType::Anthropic)
        && chat_req
            .messages
            .first()
            .map(|m| matches!(m.role, ChatRole::System))
            .unwrap_or(false);
    let tool_count = chat_req.tools.as_ref().map(|t| t.len()).unwrap_or(0);
    let tool_names: Vec<String> = chat_req
        .tools
        .as_ref()
        .map(|tools| tools.iter().map(|t| t.name.as_str().to_owned()).collect())
        .unwrap_or_default();
    log::info!(
        "[byop-diag] request summary: adapter={:?} model={} system_len={} \
         system_in_messages_head={} messages={} tools={} tool_names={:?} \
         previous_response_id_present={} store={:?} system_snippet={:?}",
        effective_adapter_kind_for(api_type, model_id, base_url),
        model_id,
        chat_req.system.as_deref().map(str::len).unwrap_or(0),
        system_in_head,
        chat_req.messages.len(),
        tool_count,
        tool_names,
        chat_req.previous_response_id.is_some(),
        chat_req.store,
        chat_req
            .system
            .as_deref()
            .map(|s| snippet_for_log(s, BYOP_DIAG_SNIPPET_CHARS))
            .unwrap_or_default(),
    );

    if let Some(tools) = &chat_req.tools {
        for (idx, tool) in tools.iter().enumerate() {
            let schema_len = tool
                .schema
                .as_ref()
                .and_then(|schema| serde_json::to_string(schema).ok())
                .map(|schema| schema.len())
                .unwrap_or(0);
            log::info!(
                "[byop-diag] request tool[{idx}]: name={} desc_len={} schema_len={} \
                 strict={:?} cache_control={:?}",
                tool.name.as_str(),
                tool.description.as_deref().map(str::len).unwrap_or(0),
                schema_len,
                tool.strict,
                tool.cache_control,
            );
        }
    }

    let flow: Vec<String> = chat_req
        .messages
        .iter()
        .enumerate()
        .map(|(idx, msg)| {
            let text_len: usize = msg.content.texts().iter().map(|t| t.len()).sum();
            let tool_call_ids: Vec<String> = msg
                .content
                .tool_calls()
                .iter()
                .map(|tc| tc.call_id.clone())
                .collect();
            let tool_response_ids: Vec<String> = msg
                .content
                .tool_responses()
                .iter()
                .map(|tr| tr.call_id.clone())
                .collect();
            format!(
                "{idx}:{:?}(text_len={text_len},tool_calls={tool_call_ids:?},tool_responses={tool_response_ids:?})",
                msg.role
            )
        })
        .collect();
    log::info!("[byop-diag] request message_flow={flow:?}");

    for (idx, msg) in chat_req.messages.iter().enumerate() {
        let mut text_count = 0;
        let mut text_total_len = 0;
        let mut first_text_snippet: Option<String> = None;
        let mut binary_summaries: Vec<String> = Vec::new();
        let mut tool_call_summaries: Vec<String> = Vec::new();
        let mut tool_response_summaries: Vec<String> = Vec::new();
        let mut thought_count = 0;
        let mut thought_total_len = 0;
        let mut reasoning_count = 0;
        let mut reasoning_total_len = 0;
        let mut custom_count = 0;

        for part in &msg.content {
            match part {
                ContentPart::Text(text) => {
                    text_count += 1;
                    text_total_len += text.len();
                    if first_text_snippet.is_none() {
                        first_text_snippet = Some(snippet_for_log(text, BYOP_DIAG_SNIPPET_CHARS));
                    }
                }
                ContentPart::Binary(binary) => {
                    binary_summaries.push(binary_for_log(binary));
                }
                ContentPart::ToolCall(tool_call) => {
                    let (args_len, args_snippet) = json_value_for_log(&tool_call.fn_arguments);
                    tool_call_summaries.push(format!(
                        "call_id={} name={} args_len={} args={} thought_signatures={}",
                        tool_call.call_id,
                        tool_call.fn_name,
                        args_len,
                        args_snippet,
                        tool_call
                            .thought_signatures
                            .as_ref()
                            .map(|s| s.len())
                            .unwrap_or(0)
                    ));
                }
                ContentPart::ToolResponse(tool_response) => {
                    tool_response_summaries.push(format!(
                        "call_id={} content_len={} placeholder={} content={}",
                        tool_response.call_id,
                        tool_response.content.len(),
                        is_placeholder_tool_response_content(&tool_response.content),
                        snippet_for_log(&tool_response.content, BYOP_DIAG_SNIPPET_CHARS)
                    ));
                }
                ContentPart::ThoughtSignature(thought) => {
                    thought_count += 1;
                    thought_total_len += thought.len();
                }
                ContentPart::ReasoningContent(reasoning) => {
                    reasoning_count += 1;
                    reasoning_total_len += reasoning.len();
                }
                ContentPart::Custom(_) => {
                    custom_count += 1;
                }
            }
        }

        let cache_control = msg
            .options
            .as_ref()
            .and_then(|options| options.cache_control.as_ref())
            .map(|cache| format!("{cache:?}"))
            .unwrap_or_else(|| "None".to_owned());
        log::info!(
            "[byop-diag] request message[{idx}]: role={:?} parts={} size={} \
             cache_control={} text_parts={} text_total_len={} first_text={:?} \
             binaries={:?} tool_calls={:?} tool_responses={:?} \
             thought_signatures={} thought_total_len={} reasoning_parts={} \
             reasoning_total_len={} custom_parts={}",
            msg.role,
            msg.content.len(),
            msg.content.size(),
            cache_control,
            text_count,
            text_total_len,
            first_text_snippet.unwrap_or_default(),
            binary_summaries,
            tool_call_summaries,
            tool_response_summaries,
            thought_count,
            thought_total_len,
            reasoning_count,
            reasoning_total_len,
            custom_count,
        );
    }

    for (idx, msg) in chat_req.messages.iter().enumerate() {
        let expected_call_ids: Vec<String> = msg
            .content
            .tool_calls()
            .iter()
            .map(|tc| tc.call_id.clone())
            .collect();
        if expected_call_ids.is_empty() {
            continue;
        }
        let next = chat_req.messages.get(idx + 1);
        let next_role = next.map(|m| format!("{:?}", m.role)).unwrap_or_default();
        let response_call_ids: Vec<String> = next
            .filter(|m| matches!(m.role, ChatRole::Tool))
            .map(|m| {
                m.content
                    .tool_responses()
                    .iter()
                    .map(|tr| tr.call_id.clone())
                    .collect()
            })
            .unwrap_or_default();
        let matched = response_call_ids == expected_call_ids;
        if matched {
            log::info!(
                "[byop-diag] request tool_pair idx={idx}: expected_call_ids={expected_call_ids:?} \
                 next_role={next_role} response_call_ids={response_call_ids:?}"
            );
        } else {
            log::warn!(
                "[byop-diag] request tool_pair mismatch idx={idx}: \
                 expected_call_ids={expected_call_ids:?} next_role={next_role} \
                 response_call_ids={response_call_ids:?}"
            );
        }
    }

    for (idx, msg) in chat_req.messages.iter().enumerate() {
        if !matches!(msg.role, ChatRole::Tool) {
            continue;
        }
        let response_call_ids: Vec<String> = msg
            .content
            .tool_responses()
            .iter()
            .map(|tr| tr.call_id.clone())
            .collect();
        let previous_expected: Vec<String> = idx
            .checked_sub(1)
            .and_then(|prev_idx| chat_req.messages.get(prev_idx))
            .filter(|prev| matches!(prev.role, ChatRole::Assistant))
            .map(|prev| {
                prev.content
                    .tool_calls()
                    .iter()
                    .map(|tc| tc.call_id.clone())
                    .collect()
            })
            .unwrap_or_default();
        if response_call_ids != previous_expected {
            log::warn!(
                "[byop-diag] request orphan_or_misordered_tool_response idx={idx}: \
                 response_call_ids={response_call_ids:?} previous_assistant_call_ids={previous_expected:?}"
            );
        }
    }
}

/// A 1:1 port of the Anthropic branch of opencode's
/// `provider/transform.ts::applyCaching`: tags the first 2 system messages + last 2
/// non-system messages with cache markers.
///
/// genai's Anthropic adapter, inside `into_anthropic_request_parts`, drops
/// `MessageOptions::cache_control` onto that message's last content part, matching
/// opencode's behavior of setting lastContent.providerOptions.anthropic.cacheControl.
///
/// **TTL choice (revised from P0-4, aligned with Zed's
/// `crates/anthropic/src/completion.rs:219-274`)**: the static prefix (system) uses 1h; the
/// conversation tail's last 2 non-system messages use 5m; meanwhile `build_chat_request`
/// tags the end of tools with 1h on the Anthropic path too (the genai Tool struct already
/// has a cache_control field).
///
/// **Motivation for the hybrid strategy**:
/// - The old "all 1h" strategy couldn't coexist with an external 5m breakpoint. When a
///   BYOP reverse proxy / upstream gateway injects a default 5m at an earlier position
///   (tools/system), Anthropic's ordering constraint rejects the subsequent 1h:
///   `a ttl='1h' cache_control block must not come after a ttl='5m'`, triggering a 400.
/// - New strategy: put all long TTLs up front (tools / system at 1h), short TTL at the end
///   of the sequence (messages at 5m), strictly matching Anthropic's processing order
///   `tools → system → messages`; if an external party stuffs an extra 5m onto tools/system,
///   it just becomes "two 5ms up front + a tail 5m", no longer triggering 1h-after-5m.
///
/// **Cost impact**:
/// - tools/system is the static prefix within a session; the 1h write's 2x base cost is
///   amortized over many hits within the whole session, effectively near-zero (a clear
///   improvement over the total cost of "all 1h" repeatedly rewriting the tail).
/// - The messages tail changes every turn; the 5m write's 1.25x base cost gets a free
///   renewal on the next turn's hit within 5 minutes, so it's not rewritten repeatedly, and
///   there's no need to commit the expensive one-time 1h write.
///
/// **TTL ordering constraint**: the Anthropic API requires that a long-TTL breakpoint must
/// come before a short-TTL one
/// (`https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching
///  #mixing-different-ttls`). This function tags system at 1h and the non-system tail at
///  5m, so the order is naturally system(1h) → messages(5m), which complies; the 1h tag
///  `build_chat_request` puts on the end of tools also comes before system, so the overall
///  order tools(1h) → system(1h) → messages(5m) still complies.
/// genai checks the order inside `into_anthropic_request_parts` and warns on violation (see
/// `lib/rust-genai/src/adapter/adapters/anthropic/adapter_impl.rs`).
fn apply_caching_anthropic(messages: &mut Vec<ChatMessage>) {
    let n = messages.len();
    if n == 0 {
        return;
    }
    let mut tag = vec![false; n];

    // first 2 system messages
    let mut sys_seen = 0;
    for (i, m) in messages.iter().enumerate() {
        if matches!(m.role, ChatRole::System) {
            tag[i] = true;
            sys_seen += 1;
            if sys_seen >= 2 {
                break;
            }
        }
    }
    // last 2 non-system messages
    let mut tail_seen = 0;
    for (i, m) in messages.iter().enumerate().rev() {
        if !matches!(m.role, ChatRole::System) {
            tag[i] = true;
            tail_seen += 1;
            if tail_seen >= 2 {
                break;
            }
        }
    }

    let original = std::mem::take(messages);
    *messages = original
        .into_iter()
        .enumerate()
        .map(|(i, m)| {
            if tag[i] {
                // ChatMessage doesn't have a direct with_cache_control; cache_control lives
                // on `MessageOptions`, injected via `with_options`.
                // `MessageOptions: From<CacheControl>` is provided by genai
                // (`chat_message.rs::impl From<CacheControl> for MessageOptions`).
                // Hybrid TTL: system uses 1h (static prefix, write cost amortized over many
                // hits within the session); non-system uses 5m (conversation tail changes
                // every turn, gets a free renewal on the next turn's hit within 5 minutes).
                // Order system(1h) → messages(5m) satisfies Anthropic's ordering constraint.
                let ttl = if matches!(m.role, ChatRole::System) {
                    CacheControl::Ephemeral1h
                } else {
                    CacheControl::Ephemeral5m
                };
                m.with_options(ttl)
            } else {
                m
            }
        })
        .collect();
}

/// Only runs after the serializer has already determined `AcceptedHistoryRepair`: converts
/// historical gaps explicitly authorized by a RepairRecord into outbound-only structured
/// ToolResponses.
///
/// Ordinary missing, duplicate, orphan, or cross-boundary out-of-order cases are already
/// blocked during the readiness-validation stage; this no longer generates placeholder
/// results for the normal flow, nor does it write back to conversation history.
fn repair_tool_call_pairs_for_accepted_history_gaps(
    messages: &mut Vec<ChatMessage>,
    repairs: &[AcceptedRepair],
    outbound_tool_groups: &[OutboundAssistantToolGroup],
) -> Result<(), ConvertToAPITypeError> {
    use std::collections::{HashMap, HashSet};

    if repairs.is_empty() {
        return Ok(());
    }

    let repair_by_key: HashMap<ToolCallKey, &AcceptedRepair> = repairs
        .iter()
        .map(|repair| (repair.tool_call.key.clone(), repair))
        .collect();
    let group_by_message_index: HashMap<usize, &OutboundAssistantToolGroup> = outbound_tool_groups
        .iter()
        .map(|group| (group.message_index, group))
        .collect();
    let mut call_id_counts: HashMap<String, usize> = HashMap::new();
    for group in outbound_tool_groups {
        for key in &group.tool_call_keys {
            *call_id_counts.entry(key.tool_call_id.clone()).or_default() += 1;
        }
    }
    let mut placeholders_inserted: Vec<String> = Vec::new();
    let mut orphan_call_ids: Vec<String> = Vec::new();
    let mut missing_without_repair: Vec<String> = Vec::new();

    let original = std::mem::take(messages);
    let mut late_responses_by_unique_call_id: HashMap<String, ToolResponse> = HashMap::new();
    let mut late_response_call_ids: HashSet<String> = HashSet::new();
    for (idx, msg) in original.iter().enumerate() {
        if msg.role != genai::chat::ChatRole::Tool {
            continue;
        }

        let is_adjacent_to_group =
            idx > 0 && group_by_message_index.contains_key(&(idx.saturating_sub(1)));
        if is_adjacent_to_group {
            continue;
        }

        for resp in msg.content.tool_responses() {
            if call_id_counts.get(&resp.call_id) == Some(&1) {
                insert_preferred_tool_response(&mut late_responses_by_unique_call_id, resp);
                late_response_call_ids.insert(resp.call_id.clone());
            }
        }
    }

    let mut rewritten: Vec<ChatMessage> = Vec::with_capacity(original.len());
    let mut idx = 0;
    while idx < original.len() {
        let msg = original[idx].clone();
        if msg.role == genai::chat::ChatRole::Tool {
            orphan_call_ids.extend(
                msg.content
                    .tool_responses()
                    .iter()
                    .filter(|response| !late_response_call_ids.contains(&response.call_id))
                    .map(|response| response.call_id.clone()),
            );
            idx += 1;
            continue;
        }

        let Some(group) = group_by_message_index.get(&idx).copied() else {
            rewritten.push(msg);
            idx += 1;
            continue;
        };

        rewritten.push(msg);
        idx += 1;

        let mut responses_by_call_id: HashMap<String, ToolResponse> = HashMap::new();
        while idx < original.len() && original[idx].role == genai::chat::ChatRole::Tool {
            for resp in original[idx].content.tool_responses() {
                insert_preferred_tool_response(&mut responses_by_call_id, resp);
            }
            idx += 1;
        }

        let mut bundled: Vec<ToolResponse> = Vec::new();
        for key in &group.tool_call_keys {
            let cid = &key.tool_call_id;
            let mut response = responses_by_call_id.remove(cid);
            if call_id_counts.get(cid) == Some(&1) {
                if let Some(late_response) = late_responses_by_unique_call_id.remove(cid) {
                    response = match response {
                        Some(existing)
                            if !should_replace_tool_response(&existing, &late_response) =>
                        {
                            Some(existing)
                        }
                        _ => Some(late_response),
                    };
                }
            }

            match response {
                Some(resp) => bundled.push(resp),
                None => {
                    if let Some(repair) = repair_by_key.get(key) {
                        placeholders_inserted.push(cid.clone());
                        bundled.push(ToolResponse::new(
                            cid.clone(),
                            repair_placeholder_content(repair.record.source),
                        ));
                    } else {
                        missing_without_repair.push(cid.clone());
                    }
                }
            }
        }

        if !bundled.is_empty() {
            rewritten.push(ChatMessage::from(bundled));
        }

        if !responses_by_call_id.is_empty() {
            orphan_call_ids.extend(responses_by_call_id.into_keys());
        }
    }

    *messages = rewritten;

    if !orphan_call_ids.is_empty() {
        log::warn!(
            "[byop-diag] accepted_history_repair: dropped {} orphan ToolResponse(s): \
             orphan_call_ids={:?}",
            orphan_call_ids.len(),
            orphan_call_ids
        );
    }
    if !placeholders_inserted.is_empty() {
        log::info!(
            "[byop-diag] accepted_history_repair: added a repair placeholder ToolResponse \
             for {} ToolCall(s): missing_call_ids={:?}",
            placeholders_inserted.len(),
            placeholders_inserted
        );
    }
    if !missing_without_repair.is_empty() {
        // When the readiness classifier has already determined AcceptedHistoryRepair, every
        // missing tool call should have a corresponding authorization in repairs; if one is
        // still missing at this point, it means the tool-call-key sources for the classifier
        // and the serializer have diverged (e.g. a future refactor of the projection or
        // outbound_tool_groups construction logic introduces a discrepancy). We can't
        // continue emitting an illegal request with a missing ToolResponse in that case —
        // must block.
        log::error!(
            "[byop-diag] accepted_history_repair: readiness-unauthorized missing \
             ToolResponse: missing_call_ids={:?}",
            missing_without_repair
        );
        return Err(ConvertToAPITypeError::Other(
            BlockedByopReadinessError::new(ReadinessCategory::MissingResultWithoutRepairSource)
                .into(),
        ));
    }
    Ok(())
}

fn repair_placeholder_content(source: RepairSource) -> String {
    json!({
        "status": "unavailable",
        "reason": source.placeholder_reason(),
        "note": REPAIR_PLACEHOLDER_NOTE,
    })
    .to_string()
}

/// Fallback: makes sure messages ends on user (or a tool response).
///
/// Trigger scenario: `AIAgentInput::ResumeConversation` doesn't append a new user message,
/// it just resends history directly. Anthropic's native API rejects a request that ends on
/// assistant (`This model does not support assistant message prefill. The conversation must
/// end with a user message.`); retrying 3 times with the same payload → the UI renders an
/// error block, triggering a flex panic.
///
/// When the end is assistant, appends `ChatMessage::user("Continue.")` to simply prompt the
/// model to continue. The Tool role, as a kind of user input (the model treats a tool
/// response as the starting point of the next turn), is left untouched. Doesn't trigger on
/// empty messages, to avoid stuffing content into an empty conversation out of nowhere.
fn ensure_ends_with_user(messages: &mut Vec<ChatMessage>) {
    use genai::chat::ChatRole;
    if let Some(last) = messages.last() {
        if last.role == ChatRole::Assistant {
            messages.push(ChatMessage::user("Continue."));
        }
    }
}

/// Appends `<environment_context>` (and the LRC snapshot) as an **independent, standalone
/// user message** to the end of the message list. Never merged into the preceding user
/// query — see the comment inside the function body for why.
///
/// This message is **rebuilt every turn, never persisted**: it carries "right now"
/// environment state, which shouldn't and can't be reproduced on historical replay. The
/// cost is that the slot it occupies is inevitably overwritten by real content next turn —
/// i.e. a divergence is inevitable there; the payoff is that every message before it stays
/// byte-for-byte constant.
///
/// This tradeoff **depends on the inference engine being able to resume computation from
/// the divergence point** (KV truncation). Measured on 2026-07-19:
///
///   qwen3-it:4b (text-only engine)  post-divergence prefill 81–183 tok / 1 chunk, TTFT ~2s
///   qwen3.5:9b (VL engine)          post-divergence prefill ~10,300 tok / 3 chunks, TTFT 33–43s
///
/// The difference isn't in Zap, it's in the model: FLM's VL / MoE engines haven't
/// implemented `set_context_length` (see the `truncate_context` at FastFlowLM's
/// `automodel.cpp:499` and the comment at `:503`), so once there's a divergence the whole
/// thing gets recomputed — this design is a net loss on that class of engine. When running
/// a local model, a text-only engine must be selected.
fn push_environment_context_message(messages: &mut Vec<ChatMessage>, env_block: String) {
    // **Always appended as its own separate message**, never merged into the trailing user
    // message.
    //
    // This used to have a "merge into it if the last message is a user message" optimization,
    // meant to avoid two consecutive user turns on a tool-result turn. Measured on
    // 2026-07-19, that turned out to be counterproductive:
    //
    //   Turn 1 (live)   message[1] = "What folder am I in?\n\n<environment_context>…"  158 bytes
    //   Turn 2 (replay) message[1] = "What folder am I in?"                            20 bytes
    //
    // The merged-in env part **doesn't** get persisted along with the query, so on the next
    // turn's replay the same message shrinks back down to the bare query — the message
    // content changes every turn, and FLM mismatches right at message[1]. This is exactly
    // the kind of drift we've been eliminating everywhere else, except this time the
    // "optimization" caused it itself.
    //
    // Keeping it as its own separate message makes the user query byte-for-byte constant,
    // and moves the divergence point to the trailing env slot (that position gets swapped
    // for a different message next turn, so it's necessarily different — but it's at the
    // tail, so the recompute cost is exactly this turn's newly added content, which is
    // theoretically optimal).
    //
    // Concern about two consecutive user turns: on the FLM side, `normalize_messages` merges
    // adjacent same-role messages, so it's harmless. Not verified for the Anthropic adapter,
    // but the current BYOP main path is OpenAI-compatible; if Anthropic is actually needed,
    // branch on api_type then — message stability must never be sacrificed for this.
    messages.push(ChatMessage::user(env_block));
}

/// Reverse direction: serializes an internal `tool_call::Tool` variant into (function name,
/// arguments JSON Value) for multi-turn history replay. The (name, args) here must strictly
/// align with each tool's `name` in `tools::REGISTRY` and the schema `from_args` expects.
fn serialize_outgoing_tool_call(
    tc: &api::message::ToolCall,
    mcp_ctx: Option<&crate::ai::agent::MCPContext>,
    server_message_data: &str,
) -> (String, Value) {
    use api::message::tool_call::Tool;

    // Recovers the carrier for a BYOP from_args parse failure: written by
    // make_tool_call_carrier_message, with tool oneof = None and the original
    // `<fn_name>\n<args_str>` encoded in server_message_data. Must be recognized before the
    // main match, or it falls through to None=>"warp_internal_empty" below, and the upstream
    // model seeing a nonexistent tool name would just be more confused and not know which
    // call failed.
    if tc.tool.is_none() {
        if let Some((fn_name, raw_args)) = server_message_data.split_once('\n') {
            if !fn_name.is_empty() {
                // When raw_args is invalid JSON (e.g. model emitted \e or \` escape),
                // fall back to an empty object so the provider receives valid JSON
                // rather than a JSON string wrapping the invalid content (which causes
                // "Invalid \escape" 400 on the next turn).
                let args_value = serde_json::from_str(raw_args).unwrap_or_else(|_| json!({}));
                return (fn_name.to_owned(), args_value);
            }
        }
    }

    // Most of the old implementation returned (String, String); here it's changed to
    // (String, Value), parsing the string once more.
    let (name, args_str) = match &tc.tool {
        Some(Tool::CallMcpTool(c)) => tools::mcp::serialize_outgoing_call(c, mcp_ctx),
        Some(Tool::ReadMcpResource(r)) => tools::mcp::serialize_outgoing_read_resource(r, mcp_ctx),
        Some(Tool::RunShellCommand(c)) => (
            "run_shell_command".to_owned(),
            json!({
                "command": c.command,
                "is_read_only": c.is_read_only,
                "uses_pager": c.uses_pager,
                "is_risky": c.is_risky,
            })
            .to_string(),
        ),
        Some(Tool::ReadFiles(r)) => {
            let files: Vec<Value> = r
                .files
                .iter()
                .map(|f| {
                    json!({
                        "path": f.name,
                        "line_ranges": f.line_ranges.iter().map(|lr| json!({
                            "start": lr.start, "end": lr.end
                        })).collect::<Vec<_>>(),
                    })
                })
                .collect();
            (
                "read_files".to_owned(),
                json!({ "files": files }).to_string(),
            )
        }
        Some(Tool::Grep(g)) => (
            "grep".to_owned(),
            json!({ "queries": g.queries, "path": g.path }).to_string(),
        ),
        Some(Tool::AskUserQuestion(a)) => {
            let questions: Vec<Value> = a
                .questions
                .iter()
                .map(|q| {
                    let (options, recommended_index, multi_select, supports_other) =
                        match &q.question_type {
                            Some(
                                api::ask_user_question::question::QuestionType::MultipleChoice(mc),
                            ) => (
                                mc.options
                                    .iter()
                                    .map(|o| o.label.clone())
                                    .collect::<Vec<_>>(),
                                mc.recommended_option_index,
                                mc.is_multiselect,
                                mc.supports_other,
                            ),
                            None => (vec![], 0, false, false),
                        };
                    json!({
                        "question": q.question,
                        "options": options,
                        "recommended_index": recommended_index,
                        "multi_select": multi_select,
                        "supports_other": supports_other,
                    })
                })
                .collect();
            (
                "ask_user_question".to_owned(),
                json!({ "questions": questions }).to_string(),
            )
        }
        Some(Tool::FileGlobV2(g)) => (
            "file_glob".to_owned(),
            json!({
                "patterns": g.patterns,
                "search_dir": g.search_dir,
                "limit": g.max_matches,
            })
            .to_string(),
        ),
        Some(Tool::ApplyFileDiffs(a)) => {
            let mut operations: Vec<Value> = Vec::new();
            for d in &a.diffs {
                operations.push(json!({
                    "op": "edit",
                    "file_path": d.file_path,
                    "search": d.search,
                    "replace": d.replace,
                }));
            }
            for f in &a.new_files {
                operations.push(json!({
                    "op": "create",
                    "file_path": f.file_path,
                    "content": f.content,
                }));
            }
            for f in &a.deleted_files {
                operations.push(json!({
                    "op": "delete",
                    "file_path": f.file_path,
                }));
            }
            (
                "apply_file_diffs".to_owned(),
                json!({ "summary": a.summary, "operations": operations }).to_string(),
            )
        }
        Some(Tool::WriteToLongRunningShellCommand(w)) => {
            use api::message::tool_call::write_to_long_running_shell_command::mode::Mode as M;
            let mode = match w.mode.as_ref().and_then(|m| m.mode.as_ref()) {
                Some(M::Raw(_)) => "raw",
                Some(M::Block(_)) => "block",
                _ => "line",
            };
            (
                "write_to_long_running_shell_command".to_owned(),
                json!({
                    "command_id": w.command_id,
                    "input": String::from_utf8_lossy(&w.input).to_string(),
                    "mode": mode,
                })
                .to_string(),
            )
        }
        Some(Tool::ReadDocuments(r)) => {
            let docs: Vec<Value> = r
                .documents
                .iter()
                .map(|d| {
                    json!({
                        "document_id": d.document_id,
                        "line_ranges": d.line_ranges.iter().map(|lr| json!({
                            "start": lr.start, "end": lr.end
                        })).collect::<Vec<_>>(),
                    })
                })
                .collect();
            (
                "read_documents".to_owned(),
                json!({ "documents": docs }).to_string(),
            )
        }
        Some(Tool::EditDocuments(e)) => {
            let diffs: Vec<Value> = e
                .diffs
                .iter()
                .map(|d| {
                    json!({
                        "document_id": d.document_id,
                        "search": d.search,
                        "replace": d.replace,
                    })
                })
                .collect();
            (
                "edit_documents".to_owned(),
                json!({ "diffs": diffs }).to_string(),
            )
        }
        Some(Tool::CreateDocuments(c)) => {
            let new_documents: Vec<Value> = c
                .new_documents
                .iter()
                .map(|d| json!({ "title": d.title, "content": d.content }))
                .collect();
            (
                "create_documents".to_owned(),
                json!({ "new_documents": new_documents }).to_string(),
            )
        }
        Some(Tool::SuggestNewConversation(s)) => (
            "suggest_new_conversation".to_owned(),
            json!({ "message_id": s.message_id }).to_string(),
        ),
        Some(Tool::SuggestPrompt(s)) => {
            use api::message::tool_call::suggest_prompt::DisplayMode;
            let (prompt, label) = match &s.display_mode {
                Some(DisplayMode::PromptChip(c)) => (c.prompt.clone(), c.label.clone()),
                Some(DisplayMode::InlineQueryBanner(b)) => (b.query.clone(), b.title.clone()),
                None => (String::new(), String::new()),
            };
            (
                "suggest_prompt".to_owned(),
                json!({ "prompt": prompt, "label": label }).to_string(),
            )
        }
        Some(Tool::OpenCodeReview(_)) => ("open_code_review".to_owned(), "{}".to_owned()),
        Some(Tool::TransferShellCommandControlToUser(t)) => (
            "transfer_shell_command_control_to_user".to_owned(),
            json!({ "reason": t.reason }).to_string(),
        ),
        Some(Tool::ReadSkill(r)) => {
            use api::message::tool_call::read_skill::SkillReference;
            // The model passed `name` in the previous turn, which `from_args` loaded into
            // the `SkillPath` slot; when serializing back into the upstream conversation
            // history, we change it back to the `name` field, consistent with the current
            // JSON schema. BundledSkillId uses the Display form `@warp-skill:<id>`,
            // consistent with SkillReference's Display.
            let name = match &r.skill_reference {
                Some(SkillReference::SkillPath(s)) => s.clone(),
                Some(SkillReference::BundledSkillId(id)) => format!("@warp-skill:{id}"),
                None => String::new(),
            };
            ("read_skill".to_owned(), json!({ "name": name }).to_string())
        }
        Some(Tool::ReadShellCommandOutput(r)) => {
            use api::message::tool_call::read_shell_command_output::Delay;
            let delay_seconds = match &r.delay {
                Some(Delay::Duration(d)) => Some(d.seconds),
                Some(Delay::OnCompletion(_)) | None => None,
            };
            let mut args = json!({ "command_id": r.command_id });
            if let Some(s) = delay_seconds {
                args["delay_seconds"] = json!(s);
            }
            ("read_shell_command_output".to_owned(), args.to_string())
        }
        Some(other) => {
            let variant_name = format!("{other:?}")
                .split('(')
                .next()
                .unwrap_or("UnknownVariant")
                .to_owned();
            (format!("warp_internal_{}", variant_name), "{}".to_owned())
        }
        None => ("warp_internal_empty".to_owned(), "{}".to_owned()),
    };
    let args_value: Value =
        serde_json::from_str(&args_str).unwrap_or(Value::Object(Default::default()));
    (name, args_value)
}

// ---------------------------------------------------------------------------
// Tools array
// ---------------------------------------------------------------------------

/// Whether this turn's input contains `UserQueryMode::Plan` triggered by `/plan`.
///
/// Per-turn semantics: only looks at whether this turn's `params.input` carries the Plan
/// marker. The current persistence path for historical task messages
/// (`make_user_query_message`) writes to the upstream proto with `..Default::default()`,
/// **without a mode field**; so plan state isn't automatically sticky across turns — the
/// user has to re-add the `/plan ` prefix on every query they want to keep read-only. This
/// is an intentional MVP shape:
/// - lowest implementation cost (no need to change the proto schema or add a new
///   conversation-level state machine)
/// - consistent with Claude Code's `EnterPlanMode` "explicit enter/exit" semantics — except
///   here the exit action is implied by "the next message doesn't have /plan"
fn is_plan_mode_turn(input: &[AIAgentInput]) -> bool {
    input.iter().any(|i| {
        matches!(
            i,
            AIAgentInput::UserQuery {
                user_query_mode: UserQueryMode::Plan,
                ..
            }
        )
    })
}

/// Names of write/execution-class built-in tools hard-filtered out under Plan Mode.
///
/// A logical fallback: even if the model ignores `partials/plan_mode.j2`'s guidance, it
/// can't trigger any side effects — a tool that's not in the tool list simply can't be
/// called (the provider protocol layer flatly rejects an unknown function).
///
/// **Write-class tools NOT blocked**: `create_documents` / `edit_documents`. They only
/// touch Zap Drive's local document storage (AIDocumentModel), never the filesystem, and
/// never run commands — semantically they're exactly the output-archiving action of Plan
/// Mode: the model settles the final plan into a Drive document, and the user can later
/// view / edit / drag it into their own PLAN folder in the Drive UI for reuse.
///
/// The remaining read-only + Drive-write subset: `read_files / grep / file_glob_v2 /
/// read_shell_command_output / ask_user_question / read_skill / read_documents /
/// create_documents / edit_documents / webfetch / websearch / mcp/*`.
const PLAN_MODE_BLOCKED_TOOLS: &[&str] = &[
    "run_shell_command",
    "apply_file_diffs",
    "write_to_long_running_shell_command",
    "open_code_review",
    "transfer_shell_command_control_to_user",
    "suggest_prompt",
];

/// Lists the tool names that will actually be fed to the upstream model this turn (built-in
/// REGISTRY + current MCP tools), sharing the same gating as `build_tools_array` (LRC /
/// `web_search_enabled` / `suggest_new_conversation` / `plan_mode`). Fed to
/// `prompt_renderer` for injection into the system prompt, so the template can render
/// dynamically off the actually-available list instead of hardcoding an allow/block list.
pub fn available_tool_names(params: &RequestParams) -> Vec<String> {
    let is_lrc = params.lrc_command_id.is_some();
    let web_enabled = params.web_search_enabled;
    let plan_mode = is_plan_mode_turn(&params.input);
    let mut names: Vec<String> = tools::REGISTRY
        .iter()
        .filter(|t| {
            if is_lrc && t.name == "run_shell_command" {
                return false;
            }
            if !web_enabled
                && (t.name == tools::webfetch::TOOL_NAME || t.name == tools::websearch::TOOL_NAME)
            {
                return false;
            }
            if t.name == "suggest_new_conversation" {
                return false;
            }
            if plan_mode && PLAN_MODE_BLOCKED_TOOLS.contains(&t.name) {
                return false;
            }
            true
        })
        .map(|t| t.name.to_owned())
        .collect();
    if let Some(ctx) = params.mcp_context.as_ref() {
        for (name, _description, _parameters) in tools::mcp::build_mcp_tool_defs(ctx) {
            names.push(name);
        }
    }
    names
}

fn build_tools_array(params: &RequestParams) -> Vec<GenaiTool> {
    // Zap A2: strips `run_shell_command` in the LRC tag-in scenario, forcing the model to
    // choose a PTY-operation-class tool instead.
    //
    // Under an alt-screen long-running command (nvim/htop) + a user in tag-in state, **the
    // mistake the model most easily makes** is calling `run_shell_command` to run
    // `taskkill nvim` / `Stop-Process nvim` (which starts a new process) — that has nothing
    // to do with the PTY that's currently running, and can't kill the target. **The correct
    // approach** is `write_to_long_running_shell_command(command_id, input=":q\n",
    // mode=raw)`, sending the instruction directly to the current PTY.
    //
    // Measured: neither system-prompt guidance nor the RunningCommand context prefix alone
    // is strong enough — the model still leans toward run_shell_command (it's simpler). The
    // cleanest hard constraint is to remove that tool directly from the tools list, so the
    // model can only pick among PTY-operation-class tools.
    //
    // Other tools are kept (read_files/grep/ask_user_question etc.), allowing the model to
    // do necessary information gathering and ask clarifying questions.
    let is_lrc = params.lrc_command_id.is_some();
    let web_enabled = params.web_search_enabled;
    let plan_mode = is_plan_mode_turn(&params.input);
    // Zap BYOP: the `suggest_prompt` chip UI has been restored via the view layer
    // subscribing to PromptSuggestionExecutorEvent (see `terminal/view.rs::
    // handle_suggest_prompt_executor_event`), so it can be exposed to the model.
    // `suggest_new_conversation` is still filtered out: there's no ready-made dialog
    // component in the UX, and the executor has been changed to fast-fail Cancelled (see
    // `action_model/execute/suggest_new_conversation.rs`) — the filter is redundant defense
    // to avoid noise from ineffective calls.
    // Dynamic placeholder substitution: some tool descriptions contain `{{year}}` (e.g.
    // websearch, aligned with opencode's description getter at websearch.ts:30-32), replaced
    // with the current year at build time. Every description the model sees carries the
    // correct year, so it isn't polluted by an old year baked into training data.
    let current_year = chrono::Local::now().format("%Y").to_string();
    let mut out: Vec<GenaiTool> = tools::REGISTRY
        .iter()
        .filter(|t| {
            if is_lrc && t.name == "run_shell_command" {
                return false;
            }
            // BYOP web tools are gated by profile.web_search_enabled (not exposed to the
            // upstream model when the user has turned off the privacy switch, to avoid an
            // accidental external network request).
            if !web_enabled
                && (t.name == tools::webfetch::TOOL_NAME || t.name == tools::websearch::TOOL_NAME)
            {
                return false;
            }
            // suggest_new_conversation: no UI implementation; Zap changed the executor to
            // fast-fail Cancelled. Filtered out here to avoid a pointless
            // tool_call→cancelled round trip if the model calls it (pure token waste).
            if t.name == "suggest_new_conversation" {
                return false;
            }
            // Plan Mode: the hard guardrail for the read-only mode triggered by `/plan`,
            // removing write/execution-class tools. Double insurance alongside the system
            // prompt's plan_mode.j2 guidance — even if the model ignores the prompt, a tool
            // not in the list can't trigger side effects (the provider protocol layer
            // flatly rejects an unknown function).
            if plan_mode && PLAN_MODE_BLOCKED_TOOLS.contains(&t.name) {
                return false;
            }
            true
        })
        .map(|t| {
            // Zap: when template hot-reloading is enabled, the override version at
            // `tool_descriptions/{name}.md` takes priority. When it's off (the default), we
            // borrow the &'static str from the registry directly, at zero extra cost.
            let raw = prompt_renderer::tool_description(t.name, t.description);
            let description = if raw.contains("{{year}}") {
                raw.replace("{{year}}", &current_year)
            } else {
                raw.into_owned()
            };
            GenaiTool::new(t.name)
                .with_description(description)
                .with_schema((t.parameters)())
        })
        .collect();

    if let Some(ctx) = params.mcp_context.as_ref() {
        for (name, description, parameters) in tools::mcp::build_mcp_tool_defs(ctx) {
            out.push(
                GenaiTool::new(name)
                    .with_description(description)
                    .with_schema(parameters),
            );
        }
    }
    if is_lrc {
        log::info!(
            "[byop] LRC tag-in: tools array filtered (removed run_shell_command), \
             total tools={}",
            out.len()
        );
    }
    if plan_mode {
        log::info!(
            "[byop] Plan Mode: tools array filtered (removed write/exec tools: {:?}), \
             total tools={}",
            PLAN_MODE_BLOCKED_TOOLS,
            out.len()
        );
    }
    out
}

// ---------------------------------------------------------------------------
// Client / routing
// ---------------------------------------------------------------------------

/// Maps `AgentProviderApiType` one-to-one onto genai's `AdapterKind`.
fn adapter_kind_for(api_type: AgentProviderApiType) -> AdapterKind {
    match api_type {
        AgentProviderApiType::OpenAi => AdapterKind::OpenAI,
        AgentProviderApiType::OpenAiResp => AdapterKind::OpenAIResp,
        AgentProviderApiType::Gemini => AdapterKind::Gemini,
        AgentProviderApiType::Anthropic => AdapterKind::Anthropic,
        AgentProviderApiType::Ollama => AdapterKind::Ollama,
        AgentProviderApiType::DeepSeek => AdapterKind::DeepSeek,
        AgentProviderApiType::Vertex => AdapterKind::Vertex,
    }
}

/// OpenAI's official gpt-5 / codex family only accept `/v1/responses` when function tools +
/// reasoning_effort are present; `/v1/chat/completions` returns 400.
fn openai_model_requires_responses_api(model_id: &str) -> bool {
    let id = model_id.to_ascii_lowercase();
    id.starts_with("gpt-5") || id.starts_with("codex")
}

/// Claude model id heuristic (tolerates namespace prefixes like
/// `anthropic/claude-sonnet-4-6`).
fn is_claude_model(model_id: &str) -> bool {
    let id = model_id.to_ascii_lowercase();
    let bare = id.rsplit('/').next().unwrap_or(&id);
    bare.contains("claude-") || bare.starts_with("claude")
}

/// Whether `base_url` points at Anthropic's official Messages API host.
fn is_anthropic_api_host(base_url: &str) -> bool {
    url::Url::parse(base_url.trim())
        .ok()
        .and_then(|u| u.host_str().map(str::to_ascii_lowercase))
        .is_some_and(|host| host == "api.anthropic.com" || host.ends_with(".anthropic.com"))
}

/// Whether `base_url` points at OpenAI's official API host. Auto-upgrading to
/// `/v1/responses` only takes effect for the official host: relays like one-api / LiteLLM
/// that are chat-completions-only often keep the official model id, and forcing a switch to
/// the Responses API there would 404.
fn is_openai_api_host(base_url: &str) -> bool {
    url::Url::parse(base_url.trim())
        .ok()
        .and_then(|u| u.host_str().map(str::to_ascii_lowercase))
        .is_some_and(|host| host == "api.openai.com" || host.ends_with(".openai.com"))
}

/// Resolves the genai adapter that should actually be used, based on the user-configured
/// `api_type`, model id, and `base_url`.
///
/// - `OpenAi` + official host + gpt-5.4 etc. → `OpenAIResp` (`/v1/responses`)
/// - `OpenAi` + `api.anthropic.com` + a claude model → `Anthropic` (`/v1/messages`)
fn effective_adapter_kind_for(
    api_type: AgentProviderApiType,
    model_id: &str,
    base_url: &str,
) -> AdapterKind {
    let base = adapter_kind_for(api_type);
    if api_type == AgentProviderApiType::OpenAi {
        if is_anthropic_api_host(base_url) && is_claude_model(model_id) {
            return AdapterKind::Anthropic;
        }
        if is_openai_api_host(base_url) && openai_model_requires_responses_api(model_id) {
            return AdapterKind::OpenAIResp;
        }
    }
    base
}

/// Normalizes the user-provided `base_url` into an endpoint URL for the genai adapter to
/// append its service path to.
///
/// All genai 0.6.x adapters assume the endpoint ends with `/` and already includes the
/// version path segment:
/// - Anthropic: `format!("{base_url}messages")` expects `…/v1/`
/// - Gemini: `format!("{base_url}models/{m}:streamGenerateContent")` expects `…/v1beta/`
/// - OpenAI / OpenAIResp / DeepSeek: `Url::join("chat/completions" or "responses")` expects
///   `…/v1/`
/// - Ollama: `format!("{base_url}api/chat")` expects the root path `…/`
///
/// Three ways users actually fill this in:
/// 1. Bare host (`https://ai.zerx.dev`) — the old default behavior of only appending a
///    trailing `/` would produce `https://ai.zerx.dev/messages`, missing `/v1/` and causing
///    a 404. **Here we automatically append the default version path segment based on
///    api_type** (Anthropic/OpenAI family → `/v1/`, Gemini → `/v1beta/`, Ollama → no
///    append).
/// 2. Full path including version (`https://ai.zerx.dev/v1`) — only append a trailing `/`,
///    leave the path alone.
/// 3. Left empty — use [`AgentProviderApiType::default_base_url`].
///
/// Extra tolerance for Anthropic: if the user pastes the full endpoint (`…/v1/messages`),
/// strip the trailing `messages` segment so genai doesn't append it again, producing
/// `…/messages/messages`.
fn normalize_endpoint_url(api_type: AgentProviderApiType, base_url: &str) -> String {
    let trimmed = base_url.trim();

    // Vertex: base_url is already the fully-formed aiplatform endpoint, built from project +
    // location by `AgentProvider::resolved_base_url` (e.g.
    // `https://us-east5-aiplatform.googleapis.com/v1/projects/p/locations/us-east5/`). The
    // default-version-path logic below is OpenAI/Anthropic/Gemini-specific and would corrupt it,
    // so pass it through, only guaranteeing the trailing `/` genai's Vertex adapter appends onto.
    if api_type == AgentProviderApiType::Vertex {
        return if trimmed.ends_with('/') {
            trimmed.to_owned()
        } else {
            format!("{trimmed}/")
        };
    }

    if trimmed.is_empty() {
        return api_type.default_base_url().to_owned();
    }

    // Parse failure (user entered a malformed URL) → fall back to the old "append trailing
    // /" behavior, letting the upstream error out instead of panicking here.
    let mut parsed = match url::Url::parse(trimmed) {
        Ok(u) => u,
        Err(_) => {
            let stripped = trimmed.trim_end_matches('/');
            return format!("{stripped}/");
        }
    };

    if api_type == AgentProviderApiType::Anthropic || is_anthropic_api_host(trimmed) {
        let path = parsed.path().trim_end_matches('/');
        if let Some(prefix) = path.strip_suffix("/messages") {
            let new_path = if prefix.is_empty() { "/" } else { prefix };
            parsed.set_path(&format!("{new_path}/"));
        }
    }

    // Ollama's native API sits at the host root `/api/chat`, with no `/v1/` prefix. Strips
    // a `/v1/` mistakenly filled into the historical default_base_url, or a `/v1` the user
    // brought over out of OpenAI habit, to avoid it being joined into `/v1/api/chat`.
    if api_type == AgentProviderApiType::Ollama {
        let path = parsed.path().trim_end_matches('/');
        if path.is_empty() || path == "/" || path == "/v1" {
            let mut normalized = parsed.clone();
            normalized.set_path("/");
            return normalized.to_string();
        }
    }

    // path == "/" or empty → the user only filled in a host, so automatically append the
    // api_type's default version path segment.
    if parsed.path() == "/" || parsed.path().is_empty() {
        // Extract the path portion from default_base_url (e.g. "/v1/" / "/v1beta/" / "/").
        let default_path = url::Url::parse(api_type.default_base_url())
            .ok()
            .map(|u| u.path().to_owned())
            .unwrap_or_else(|| "/".to_owned());
        let host_part = trimmed.trim_end_matches('/');
        return format!("{host_part}{default_path}");
    }

    // The user already supplied a path → just make sure it has a trailing `/` (both genai's
    // format!/Url::join depend on it).
    let normalized = parsed.to_string();
    let stripped = normalized.trim_end_matches('/');
    format!("{stripped}/")
}

/// Builds the genai Client. Newly created on every request (cheap — a Client internally is
/// just a reqwest::Client + adapter table). `ServiceTargetResolver` captures the current
/// request's endpoint/key/api_type and forces every `exec_chat_stream` call to route to the
/// specified AdapterKind, completely bypassing genai's default "guess by model name".
/// A small-capacity LRU cache for `build_client`.
///
/// BYOP goes through `build_client` on every conversation turn; without caching, the Client
/// would be rebuilt every time, dropping the underlying reqwest connection pool along with
/// it, causing every message to redo a TCP+TLS handshake against the provider (about
/// 100–300ms per turn on cloud providers like OpenRouter, more noticeable through a proxy).
/// The key covers all inputs that affect the build result, so any change (switching
/// provider / changing the API key / changing proxy settings) misses and rebuilds.
///
/// Capacity >1: the main conversation model and the title_model / oneshot (see
/// `oneshot.rs`) may be different providers; a single slot would repeatedly evict each
/// other as they alternate.
const BYOP_CLIENT_CACHE_CAP: usize = 4;

struct CachedByopClient {
    api_type: AgentProviderApiType,
    base_url: String,
    api_key: String,
    proxy_fingerprint: String,
    client: Client,
}

static BYOP_CLIENT_CACHE: std::sync::Mutex<Vec<CachedByopClient>> =
    std::sync::Mutex::new(Vec::new());

fn proxy_fingerprint(cfg: &http_client::ProxyConfig) -> String {
    format!(
        "{}|{}|{}|{}|{}",
        cfg.mode.as_str(),
        cfg.url,
        cfg.username,
        cfg.password,
        cfg.no_proxy
    )
}

pub(super) fn build_client(
    api_type: AgentProviderApiType,
    base_url: &str,
    api_key: String,
) -> Client {
    let proxy_fp = proxy_fingerprint(&current_proxy_config());
    {
        let mut cache = BYOP_CLIENT_CACHE
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(pos) = cache.iter().position(|c| {
            c.api_type == api_type
                && c.base_url == base_url
                && c.api_key == api_key
                && c.proxy_fingerprint == proxy_fp
        }) {
            // Move-to-front to maintain LRU order.
            let hit = cache.remove(pos);
            let client = hit.client.clone();
            cache.insert(0, hit);
            return client;
        }
    }
    let client = build_client_uncached(api_type, base_url, api_key.clone());
    {
        let mut cache = BYOP_CLIENT_CACHE
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        cache.insert(
            0,
            CachedByopClient {
                api_type,
                base_url: base_url.to_owned(),
                api_key,
                proxy_fingerprint: proxy_fp,
                client: client.clone(),
            },
        );
        cache.truncate(BYOP_CLIENT_CACHE_CAP);
    }
    client
}

fn build_client_uncached(
    api_type: AgentProviderApiType,
    base_url: &str,
    api_key: String,
) -> Client {
    let endpoint_url = normalize_endpoint_url(api_type, base_url);
    log::info!("[byop] build_client: api_type={api_type:?} endpoint_url={endpoint_url}");
    // Vertex mints a short-lived OAuth2 bearer per request, so it needs an async resolver; every
    // other type routes through the synchronous static-key path below.
    let resolver = if api_type == AgentProviderApiType::Vertex {
        build_vertex_resolver(endpoint_url.clone(), api_key.clone())
    } else {
    let key_for_resolver = api_key.clone();
    ServiceTargetResolver::from_resolver_fn(
        move |service_target: ServiceTarget| -> Result<ServiceTarget, genai::resolver::Error> {
            let ServiceTarget { model, .. } = service_target;
            let endpoint = Endpoint::from_owned(endpoint_url.clone());
            let auth = AuthData::from_single(key_for_resolver.clone());
            let model_name = model.model_name.as_str();
            let adapter_kind = effective_adapter_kind_for(api_type, model_name, &endpoint_url);
            if api_type == AgentProviderApiType::OpenAi && adapter_kind == AdapterKind::OpenAIResp {
                log::info!(
                    "[byop] auto-upgrade OpenAi → OpenAIResp for model={model_name} \
                     (function tools + reasoning_effort require /v1/responses)"
                );
            }
            if api_type == AgentProviderApiType::OpenAi && adapter_kind == AdapterKind::Anthropic {
                log::info!(
                    "[byop] auto-upgrade OpenAi → Anthropic for model={model_name} \
                     (official Anthropic host requires /v1/messages)"
                );
            }
            // Overrides genai's "guess by model name" result with our specified AdapterKind,
            // but keeps model_name so the upstream service can correctly address the model.
            let model = ModelIden::new(adapter_kind, model.model_name);
            Ok(ServiceTarget {
                endpoint,
                auth,
                model,
            })
        },
        )
    };

    // Zap BYOP: the SSE stream must not use gzip. `Accept-Encoding: gzip` makes an
    // nginx-style proxy compress the response, and the server has to flush a complete
    // deflate frame before the client can decode plaintext out of it — streaming semantics
    // get broken into ~K-byte bursts, which feels like "stuttering every few hundred ms".
    // zed/opencode use native fetch / std HTTP and don't proactively negotiate gzip on SSE,
    // so they're unaffected behind the same proxy.
    //
    // We explicitly construct `WebConfig` here even though genai's default is already
    // `gzip=false` (a fork modification).
    //
    // User-Agent is dynamically bound to the current app name (taken from
    // `ChannelState::app_id().application_name()`, registered by the entry-point bin:
    // `bin/oss.rs` → "Zap"; other channels bring their own name). This way the upstream
    // service can identify which branch build the request came from, and it automatically
    // follows if the name is changed later.
    let mut headers = reqwest::header::HeaderMap::new();
    if let Ok(value) = build_user_agent_header() {
        headers.insert(reqwest::header::USER_AGENT, value);
    }
    let mut web_config = WebConfig {
        gzip: false,
        default_headers: Some(headers),
        ..WebConfig::default()
    };
    let proxy_cfg = current_proxy_config();
    match proxy_cfg.mode {
        http_client::ProxyMode::Off => {
            // Completely disables the proxy (including the system proxy and environment
            // variables), aligned with http_client::Client::new()'s Off behavior.
            web_config.no_proxy = true;
        }
        http_client::ProxyMode::System => {
            // Follows the system/environment-variable proxy (reqwest's default behavior).
            // WebConfig doesn't set a proxy → reqwest reads macOS SystemConfiguration or
            // the HTTP_PROXY / HTTPS_PROXY environment variables.
        }
        http_client::ProxyMode::Custom => {
            if !proxy_cfg.url.is_empty() {
                if let Err(err) = web_config.set_proxy_settings(
                    &proxy_cfg.url,
                    &proxy_cfg.username,
                    &proxy_cfg.password,
                    &proxy_cfg.no_proxy,
                ) {
                    log::warn!(
                        "[byop] proxy URL '{}' is invalid, skipping proxy configuration: {err}",
                        proxy_cfg.url
                    );
                }
            }
        }
    }
    Client::builder()
        .with_web_config(web_config)
        .with_service_target_resolver(resolver)
        .build()
}

/// Builds the async `ServiceTargetResolver` for Vertex AI.
///
/// Unlike the static-key resolver, this awaits [`super::vertex_auth::access_token`] on every
/// request to obtain a fresh GCP OAuth2 bearer (gcloud caches + refreshes underneath), while the
/// surrounding genai `Client` — and its reqwest connection pool — is still cached by
/// `build_client` (Vertex's cache key is stable: the endpoint encodes project+location and the
/// credential string doesn't change). The endpoint (already built from project+location by
/// `normalize_endpoint_url`) and `AdapterKind::Vertex` are pinned here so genai does not fall
/// back to guessing the adapter by model name.
fn build_vertex_resolver(endpoint_url: String, credential: String) -> ServiceTargetResolver {
    ServiceTargetResolver::from_resolver_async_fn(move |service_target: ServiceTarget| {
        let endpoint_url = endpoint_url.clone();
        let credential = credential.clone();
        Box::pin(async move {
            let ServiceTarget { model, .. } = service_target;
            let token = super::vertex_auth::access_token(&credential)
                .await
                .map_err(genai::resolver::Error::Custom)?;
            let endpoint = Endpoint::from_owned(endpoint_url);
            let auth = AuthData::from_single(token);
            // Override genai's "guess by model name"; keep model_name so the Vertex adapter can
            // route to publishers/google (gemini*) or publishers/anthropic (claude*).
            let model = ModelIden::new(AdapterKind::Vertex, model.model_name);
            Ok(ServiceTarget {
                endpoint,
                auth,
                model,
            })
        }) as std::pin::Pin<
            Box<dyn std::future::Future<Output = genai::resolver::Result<ServiceTarget>> + Send>,
        >
    })
}

/// Builds the `User-Agent` header for BYOP outbound requests, in the form:
/// - `Zap/<git-tag>` — when a release build has `GIT_RELEASE_TAG` injected
/// - `Zap` — for Dev / local builds with no version
///
/// The app name is the user-facing product name (`ChannelState::display_name()`), so the
/// User-Agent reflects the brand ("Phosphor") rather than the storage-facing app id name.
fn build_user_agent_header(
) -> Result<reqwest::header::HeaderValue, reqwest::header::InvalidHeaderValue> {
    let app_name = warp_core::channel::ChannelState::display_name();
    let ua = match warp_core::channel::ChannelState::app_version() {
        Some(v) if !v.is_empty() => format!("{app_name}/{v}"),
        _ => app_name,
    };
    reqwest::header::HeaderValue::from_str(&ua)
}

/// Determines whether to inject `enable_thinking: true` for DashScope (Alibaba Cloud
/// Bailian, OpenAI-compatible path).
///
/// Aligned with opencode's `transform.ts:931-938` (comment at provider/transform.ts L926+):
/// "DashScope doesn't turn on thinking by default; reasoning models like qwen3 / qwq /
/// deepseek-r1 / kimi-k2.5 / qwen-plus must explicitly set `enable_thinking: true` to output
/// reasoning_content."
///
/// Trigger conditions (all must hold):
/// 1. `api_type == OpenAi` (DashScope goes through the OpenAI-compatible path)
/// 2. `effort_setting != Off` (respected when the user has actively turned off thinking —
///    don't inject)
/// 3. base_url contains `dashscope.aliyuncs.com` / `dashscope.cn` /
///    `dashscope-intl.aliyuncs.com`
/// 4. model_id doesn't contain `kimi-k2-thinking` (excluded by opencode — that model is
///    already thinking by default)
/// 5. model_id matches the reasoning substring allowlist: `qwen3` / `qwq` / `deepseek-r1` /
///    `kimi-k2.5` / `kimi-k2-` / `qwen-plus` (avoids indiscriminately injecting it for
///    pure-chat models like qwen-turbo / qwen2.5)
fn dashscope_needs_enable_thinking(
    api_type: AgentProviderApiType,
    base_url: &str,
    model_id: &str,
    effort_setting: crate::settings::ReasoningEffortSetting,
) -> bool {
    if !matches!(api_type, AgentProviderApiType::OpenAi) {
        return false;
    }
    if matches!(effort_setting, crate::settings::ReasoningEffortSetting::Off) {
        return false;
    }
    let url = base_url.to_ascii_lowercase();
    let is_dashscope = url.contains("dashscope.aliyuncs.com")
        || url.contains("dashscope.cn")
        || url.contains("dashscope-intl.aliyuncs.com");
    if !is_dashscope {
        return false;
    }
    let id = model_id.to_ascii_lowercase();
    if id.contains("kimi-k2-thinking") {
        return false;
    }
    id.contains("qwen3")
        || id.contains("qwq")
        || id.contains("deepseek-r1")
        || id.contains("kimi-k2.5")
        || id.contains("kimi-k2-")
        || id.contains("qwen-plus")
}

/// Infers the upstream provider from `base_url`, used **only** to decide whether to send
/// `prompt_cache_key`.
///
/// Aligned with the `options()` function in opencode's
/// `packages/opencode/src/provider/transform.ts`: opencode decides whether to set
/// `promptCacheKey` based on the `providerID` dimension — only the five providers `openai` /
/// `azure` / `openrouter` / `venice` / `opencode*` send it. All other providers (including
/// all OpenAI-compatible relays / local services / most domestic-China cloud providers)
/// never send it.
///
/// Zap has no `providerID` dimension on this side, only the `base_url` the user freely
/// types in. So we infer it from `base_url`:
/// - `api.openai.com`           → "openai"
/// - `*.openai.azure.com`       → "azure"
/// - `openrouter.ai/api`        → "openrouter"
/// - `api.venice.ai/api`        → "venice"
/// - `opencode.ai/zen`          → "opencode"
///
/// Everything else returns `None` (equivalent to not matching any branch in opencode).
///
/// Data source: the `api` field of the provider table at
/// [models.dev](https://models.dev/api.json). openai / azure / venice have no `api` entry in
/// models.dev (it's baked into the SDK), so those are hardcoded here per each SDK's default
/// endpoint.
///
/// Deliberately covers only these 5 — this is opencode's actual allowlist; don't expand it
/// yourself just because "there seem to be other cache-compatible providers." OpenRouter's
/// docs natively support `prompt_cache_key` (snake_case); the other four go through the
/// OpenAI Chat Completions path.
fn opencode_compatible_cache_provider(base_url: &str) -> bool {
    let u = base_url.to_ascii_lowercase();
    u.contains("api.openai.com")
        || u.contains(".openai.azure.com")
        || u.contains("openrouter.ai/api")
        || u.contains("api.venice.ai/api")
        || u.contains("opencode.ai/zen")
}

fn build_chat_options(
    api_type: AgentProviderApiType,
    base_url: &str,
    model_id: &str,
    effort_setting: crate::settings::ReasoningEffortSetting,
    extra_headers: Vec<(String, String)>,
    conversation_id: Option<&str>,
) -> ChatOptions {
    let mut opts = ChatOptions::default()
        .with_capture_content(true)
        .with_capture_tool_calls(true)
        .with_capture_reasoning_content(true)
        .with_capture_usage(true)
        // Makes genai extract the <think>...</think> segment that DeepSeek-style models
        // embed in content and fold it into a reasoning chunk, so the UI displays more
        // cleanly. Only takes effect on adapters that support this format.
        .with_normalize_reasoning_content(true);

    // Prompt caching (1:1 aligned with the `options()` function in opencode's
    // `packages/opencode/src/provider/transform.ts`). Key points:
    //
    // 1. **The `prompt_cache_retention` field (genai `ChatOptions::cache_control`) is never
    //    sent**. opencode's whole repo never uses this field; strict-schema-validating BYOP
    //    relays (OpenCode Go / vLLM / lm-studio / most domestic-China proxies) reject it
    //    with HTTP 400 `Extra inputs are not permitted, field: 'prompt_cache_retention'`
    //    (issue #126). Even OpenAI official has 5min implicit caching by default, so it
    //    doesn't need to be declared explicitly.
    //
    // 2. **`prompt_cache_key` is only sent for opencode's 5 known providers**: `openai` /
    //    `azure` / `openrouter` / `venice` / `opencode`. All other providers (including all
    //    OpenAI-compatible relays / domestic-China clouds / local services) never send it.
    //
    //    opencode decides this using `providerID` (a string the user picks in config); Zap
    //    has no `providerID` on this side, so it can only be inferred from `base_url` → see
    //    `opencode_compatible_cache_provider`. This is base_url's only semantic use here —
    //    don't extend it to decide any behavior beyond caching.
    //
    // 3. Anthropic goes through per-message cache_control (in `build_chat_request`), not
    //    here.
    // 4. DeepSeek / Gemini / Ollama cache implicitly server-side, so skipped.
    if matches!(
        api_type,
        AgentProviderApiType::OpenAi | AgentProviderApiType::OpenAiResp
    ) && opencode_compatible_cache_provider(base_url)
    {
        if let Some(cid) = conversation_id {
            if !cid.is_empty() {
                opts = opts.with_prompt_cache_key(cid.to_owned());
            }
        }
    }

    // **Thinking-depth tier submission** (aligned with how Zed's
    // `LanguageModelRequest::thinking_allowed` handles each provider: when
    // `thinking_allowed=false`, no provider sends any thinking field, since Anthropic /
    // Google / Bedrock all default to thinking-off server-side).
    //
    // - **Auto**: don't pass anything, let genai use "infer from model-name suffix"
    //   (inside the OpenAI/Anthropic adapters).
    // - **Off + Anthropic / Gemini**: **skip `with_reasoning_effort` entirely**, equivalent
    //   to Auto + a model name with no thinking suffix. The genai adapter takes the
    //   `(model, None)` inference branch, doesn't call `insert_anthropic_reasoning` /
    //   `thinkingConfig`, and sends no thinking field.
    //   ★ This conveniently sidesteps a bug in vendor genai where `claude-opus-4-6` /
    //   `claude-sonnet-4-6`'s `support_adaptive` forcibly injects
    //   `thinking:{type:adaptive}` (`lib/rust-genai/src/adapter/adapters/anthropic/adapter_impl.rs:121-135`
    //   doesn't check whether effort is `None`).
    // - **Off + DeepSeek**: `thinking_mode` defaults to on server-side (deepseek-v4-flash
    //   etc.), and needs an explicit `extra_body.thinking.type=disabled` to turn it off.
    //   Zap's local genai fork already supports top-level merging via
    //   `ChatOptions::extra_body`.
    // - **Off + OpenAI / OpenAiResp**: goes through the `reasoning_effort: "none"` path
    //   (GPT-5 / codex accept the `none` tier; o-series is filtered by the capability
    //   table).
    // - **Non-Off + model doesn't support reasoning**: skipped, to avoid injecting thinking
    //   params into old models like claude-3-5-haiku / gpt-4o / gemini-1.5-pro and getting a
    //   400 from upstream.
    use crate::settings::ReasoningEffortSetting as RE;
    match (api_type, effort_setting) {
        // Auto: no parameters sent
        (_, RE::Auto) => {}

        // Anthropic + Off: no thinking field sent
        (AgentProviderApiType::Anthropic, RE::Off) => {
            log::info!(
                "[byop] Anthropic Off → skip reasoning_effort (model={model_id}); \
                 no thinking field sent"
            );
        }

        // Gemini + Off: no thinkingConfig sent
        (AgentProviderApiType::Gemini, RE::Off) => {
            log::info!(
                "[byop] Gemini Off → skip reasoning_effort (model={model_id}); \
                 no thinkingConfig sent"
            );
        }

        // DeepSeek + Off: explicit disabled
        (AgentProviderApiType::DeepSeek, RE::Off) => {
            log::info!(
                "[byop] DeepSeek Off → extra_body thinking.type=disabled (model={model_id})"
            );
            opts = opts.with_extra_body(json!({"thinking": {"type": "disabled"}}));
        }

        // Everything else (OpenAI / OpenAiResp / Ollama / each provider's non-Off tiers):
        // goes through the reasoning_effort injection path after capability-table filtering
        _ => {
            if let Some(effort) = effort_setting.to_genai() {
                if super::reasoning::model_supports_reasoning(api_type, model_id) {
                    log::info!(
                        "[byop] reasoning_effort injected: model={model_id} setting={effort_setting:?}"
                    );
                    opts = opts.with_reasoning_effort(effort);
                } else {
                    log::info!(
                        "[byop] reasoning_effort SKIPPED: model={model_id} not in capability list \
                         (api_type={api_type:?} setting={effort_setting:?}); request sent without thinking params"
                    );
                }
            }
        }
    }

    // DashScope's (Alibaba Cloud Bailian) OpenAI-compatible path needs an explicit
    // `enable_thinking: true` to output reasoning. See the `dashscope_needs_enable_thinking`
    // comment for details. Mutually exclusive with the DeepSeek-Off extra_body above
    // (DeepSeek goes through the DeepSeek api_type, DashScope through the OpenAI api_type),
    // so they never fire simultaneously.
    if dashscope_needs_enable_thinking(api_type, base_url, model_id, effort_setting) {
        log::info!(
            "[byop] DashScope reasoning model → extra_body enable_thinking=true \
             (model={model_id} setting={effort_setting:?})"
        );
        opts = opts.with_extra_body(json!({"enable_thinking": true}));
    }
    if !extra_headers.is_empty() {
        opts = opts.with_extra_headers(extra_headers);
    }

    opts
}

fn map_genai_error(err: genai::Error) -> OpenAiCompatibleError {
    use genai::Error as G;
    match err {
        // True parse failures: during JSON deserialization
        G::StreamParse { .. }
        | G::SerdeJson(_)
        | G::JsonValueExt(_)
        | G::InvalidJsonResponseElement { .. } => OpenAiCompatibleError::Decode(format!("{err}")),

        // Failures during the network/streaming-send stage (reqwest connection, TLS, DNS,
        // timeout, stream interruption, etc.)
        G::WebStream { .. } | G::WebAdapterCall { .. } | G::WebModelCall { .. } => {
            OpenAiCompatibleError::Stream(format!("{err}"))
        }

        // An HTTP error status returned by the server
        G::HttpError {
            status,
            body,
            canonical_reason,
        } => OpenAiCompatibleError::Status {
            status: status.as_u16(),
            body: if canonical_reason.is_empty() {
                body
            } else {
                format!("{canonical_reason}: {body}")
            },
        },

        // Everything else (request construction, auth, unsupported capability, etc.) is
        // classified as a generic error, to avoid being misleadingly labeled "parse failure"
        other => OpenAiCompatibleError::Other(format!("{other}")),
    }
}

