/// Once BYOP webfetch finishes, assembles a Success card by extracting `url` + HTTP
/// `status` from the `FetchOutput` JSON; status="error" takes the Error card instead.
fn make_web_fetch_status_from_result(
    task_id: &str,
    request_id: &str,
    fallback_urls: &[String],
    result_json: &Value,
) -> api::Message {
    let is_error = result_json.get("status").and_then(|v| v.as_str()) == Some("error");
    let r#type = if is_error {
        api::message::web_fetch::status::Type::Error(())
    } else {
        let url = result_json
            .get("url")
            .and_then(|v| v.as_str())
            .map(|s| s.to_owned())
            .unwrap_or_else(|| fallback_urls.first().cloned().unwrap_or_default());
        // FetchOutput.status is an HTTP status code; 2xx counts as success.
        let success = result_json
            .get("status")
            .and_then(|v| v.as_u64())
            .map(|c| (200..300).contains(&c))
            .unwrap_or(true);
        api::message::web_fetch::status::Type::Success(api::message::web_fetch::status::Success {
            pages: vec![api::message::web_fetch::status::success::FetchedPage {
                url,
                title: String::new(),
                success,
            }],
        })
    };
    api::Message {
        id: Uuid::new_v4().to_string(),
        task_id: task_id.to_owned(),
        server_message_data: String::new(),
        citations: vec![],
        message: Some(api::message::Message::WebFetch(api::message::WebFetch {
            status: Some(api::message::web_fetch::Status {
                r#type: Some(r#type),
            }),
        })),
        request_id: request_id.to_owned(),
        timestamp: None,
    }
}

fn make_tool_call_result_message(
    task_id: &str,
    request_id: &str,
    tool_call_id: String,
    content: String,
) -> api::Message {
    // ToolCallResult persistence: warp protobuf's `tool_call_result.result` oneof only has
    // structured variants (RunShellCommand / Grep / ReadFiles / ...) — there's no generic
    // string fallback variant. BYOP already serializes result into a JSON string itself in
    // chat_stream, so there's no need to structure it per the warp protocol — we just store
    // the string directly into the free-form string field `server_message_data`, and leave
    // the `result` oneof as None. The next turn's build_chat_request needs a special case
    // in the `Message::ToolCallResult` branch: when result=None, read content from
    // server_message_data instead (otherwise it goes through tools::serialize_result to
    // deserialize the structured variant).
    api::Message {
        id: Uuid::new_v4().to_string(),
        task_id: task_id.to_owned(),
        server_message_data: content,
        citations: vec![],
        message: Some(api::message::Message::ToolCallResult(
            api::message::ToolCallResult {
                tool_call_id,
                context: None,
                result: None,
            },
        )),
        request_id: request_id.to_owned(),
        timestamp: None,
    }
}

/// When BYOP's `from_args` fails to parse, emits a placeholder ToolCall as a carrier: the
/// `tool` oneof is left None (no suitable structured variant), and the original fn_name +
/// args_str are encoded into `server_message_data` as `<fn_name>\n<args_str>`. The next
/// turn's build_chat_request → `serialize_outgoing_tool_call`'s carrier branch restores it
/// from this, ensuring the tool_use name / args the upstream model sees match the original
/// call (otherwise falling back to a "warp_internal_empty" placeholder would confuse the
/// model, and wouldn't line up with the ToolCallResult error context that follows it).
fn make_tool_call_carrier_message(
    task_id: &str,
    request_id: &str,
    tool_call_id: &str,
    fn_name: &str,
    args_str: &str,
) -> api::Message {
    let carrier = format!("{}\n{}", fn_name, args_str);
    api::Message {
        id: Uuid::new_v4().to_string(),
        task_id: task_id.to_owned(),
        server_message_data: carrier,
        citations: vec![],
        message: Some(api::message::Message::ToolCall(api::message::ToolCall {
            tool_call_id: tool_call_id.to_owned(),
            tool: None,
        })),
        request_id: request_id.to_owned(),
        timestamp: None,
    }
}

fn make_tool_call_message(
    task_id: &str,
    request_id: &str,
    tool_call_id: &str,
    tool: api::message::tool_call::Tool,
) -> api::Message {
    api::Message {
        id: Uuid::new_v4().to_string(),
        task_id: task_id.to_owned(),
        server_message_data: String::new(),
        citations: vec![],
        message: Some(api::message::Message::ToolCall(api::message::ToolCall {
            tool_call_id: tool_call_id.to_owned(),
            tool: Some(tool),
        })),
        request_id: request_id.to_owned(),
        timestamp: None,
    }
}

fn create_task_event(task_id: &str) -> api::ResponseEvent {
    api::ResponseEvent {
        r#type: Some(api::response_event::Type::ClientActions(
            api::response_event::ClientActions {
                actions: vec![api::ClientAction {
                    action: Some(api::client_action::Action::CreateTask(
                        api::client_action::CreateTask {
                            task: Some(api::Task {
                                id: task_id.to_owned(),
                                description: String::new(),
                                dependencies: None,
                                messages: vec![],
                                summary: String::new(),
                                server_data: String::new(),
                            }),
                        },
                    )),
                }],
            },
        )),
    }
}

/// Builds an `Action::CreateTask` representing a new subtask, with
/// `dependencies.parent_task_id` set. When conversation sees `task.parent_id()` is non-empty
/// in `apply_client_action::CreateTask` → it takes the `Task::new_subtask` path, finds the
/// matching subagent tool_call in parent.messages, extracts `SubagentParams` to attach to
/// the subtask, and emits `BlocklistAIHistoryEvent::CreatedSubtask`. The LRC tag-in floating
/// window spawn pipeline depends on this event.
fn create_subtask_event(subtask_id: &str, parent_task_id: &str) -> api::ResponseEvent {
    api::ResponseEvent {
        r#type: Some(api::response_event::Type::ClientActions(
            api::response_event::ClientActions {
                actions: vec![api::ClientAction {
                    action: Some(api::client_action::Action::CreateTask(
                        api::client_action::CreateTask {
                            task: Some(api::Task {
                                id: subtask_id.to_owned(),
                                description: String::new(),
                                dependencies: Some(api::task::Dependencies {
                                    parent_task_id: parent_task_id.to_owned(),
                                }),
                                messages: vec![],
                                summary: String::new(),
                                server_data: String::new(),
                            }),
                        },
                    )),
                }],
            },
        )),
    }
}

fn make_finished_done(
    usage_metadata: Option<api::response_event::stream_finished::ConversationUsageMetadata>,
) -> api::ResponseEvent {
    api::ResponseEvent {
        r#type: Some(api::response_event::Type::Finished(
            api::response_event::StreamFinished {
                reason: Some(api::response_event::stream_finished::Reason::Done(
                    api::response_event::stream_finished::Done {},
                )),
                conversation_usage_metadata: usage_metadata,
                token_usage: vec![],
                should_refresh_model_config: false,
                request_cost: None,
            },
        )),
    }
}

#[cfg(test)]
mod assistant_buffer_tests {
    use super::*;
    use genai::chat::{ChatRole, ToolCall};

    fn reasoning_part(msg: &ChatMessage) -> Option<&str> {
        for p in msg.content.parts() {
            if let ContentPart::ReasoningContent(r) = p {
                return Some(r.as_str());
            }
        }
        None
    }

    /// gate=false + real reasoning → **discarded** (the zerx-lab/warp #25 fix point).
    /// OpenAI-strict providers like Cerebras / Groq / OpenRouter 400 as soon as they see
    /// the field.
    #[test]
    fn no_echo_drops_real_reasoning_text() {
        let mut buf = AssistantBuffer::new(false);
        buf.text = Some("Hi".to_string());
        buf.reasoning = Some("internal thought".to_string());
        let mut msgs = Vec::new();
        buf.flush_into(&mut msgs);
        assert_eq!(msgs.len(), 1);
        assert_eq!(msgs[0].role, ChatRole::Assistant);
        assert!(
            reasoning_part(&msgs[0]).is_none(),
            "must not echo reasoning"
        );
    }

    /// gate=false + tool_calls + real reasoning → the tool_calls message doesn't get
    /// reasoning attached either.
    #[test]
    fn no_echo_drops_reasoning_on_tool_calls_message() {
        let mut buf = AssistantBuffer::new(false);
        buf.text = Some("calling".to_string());
        buf.tool_calls = vec![ToolCall {
            call_id: "c1".to_string(),
            fn_name: "echo".to_string(),
            fn_arguments: serde_json::json!({}),
            thought_signatures: None,
        }];
        buf.reasoning = Some("planning".to_string());
        let mut msgs = Vec::new();
        buf.flush_into(&mut msgs);
        assert_eq!(msgs.len(), 2, "text + tool_calls should flush into two messages");
        for m in &msgs {
            assert!(
                reasoning_part(m).is_none(),
                "any-msg reasoning must be absent"
            );
        }
    }

    /// gate=true + real reasoning → attaches the real value (the DeepSeek / Kimi path).
    #[test]
    fn echo_keeps_real_reasoning() {
        let mut buf = AssistantBuffer::new(true);
        buf.text = Some("ok".to_string());
        buf.reasoning = Some("thinking...".to_string());
        let mut msgs = Vec::new();
        buf.flush_into(&mut msgs);
        assert_eq!(msgs.len(), 1);
        assert_eq!(reasoning_part(&msgs[0]), Some("thinking..."));
    }

    /// gate=true + no reasoning → attaches the placeholder (satisfies the "field must be
    /// present" validation).
    #[test]
    fn echo_inserts_placeholder_when_empty() {
        let mut buf = AssistantBuffer::new(true);
        buf.text = Some("ok".to_string());
        buf.reasoning = None;
        let mut msgs = Vec::new();
        buf.flush_into(&mut msgs);
        assert_eq!(msgs.len(), 1);
        assert_eq!(reasoning_part(&msgs[0]), Some(REASONING_ECHO_PLACEHOLDER));
    }

    /// gate=true + tool_calls + real reasoning → the text message gets the placeholder, the
    /// tool_calls message gets the real value.
    #[test]
    fn echo_with_tool_calls_splits_correctly() {
        let mut buf = AssistantBuffer::new(true);
        buf.text = Some("calling".to_string());
        buf.tool_calls = vec![ToolCall {
            call_id: "c1".to_string(),
            fn_name: "echo".to_string(),
            fn_arguments: serde_json::json!({}),
            thought_signatures: None,
        }];
        buf.reasoning = Some("plan".to_string());
        let mut msgs = Vec::new();
        buf.flush_into(&mut msgs);
        assert_eq!(msgs.len(), 2);
        // The text message: placeholder
        assert_eq!(reasoning_part(&msgs[0]), Some(REASONING_ECHO_PLACEHOLDER));
        // The tool_calls message: real reasoning + contains a ToolCall part
        assert_eq!(reasoning_part(&msgs[1]), Some("plan"));
        assert!(
            !msgs[1].content.tool_calls().is_empty(),
            "second message must carry tool_calls"
        );
    }
}

#[cfg(test)]
mod dashscope_thinking_tests {
    use super::*;
    use crate::settings::ReasoningEffortSetting as R;

    const DASHSCOPE_CN: &str = "https://dashscope.aliyuncs.com/compatible-mode/v1/";
    const DASHSCOPE_INTL: &str = "https://dashscope-intl.aliyuncs.com/compatible-mode/v1/";

    #[test]
    fn dashscope_qwen3_triggers() {
        assert!(dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "qwen3-235b-a22b",
            R::High
        ));
    }

    #[test]
    fn dashscope_qwq_triggers() {
        assert!(dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_INTL,
            "qwq-32b",
            R::Medium
        ));
    }

    #[test]
    fn dashscope_deepseek_r1_triggers() {
        assert!(dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "deepseek-r1",
            R::High
        ));
    }

    #[test]
    fn dashscope_kimi_k2_thinking_excluded() {
        // opencode's comment: kimi-k2-thinking is already on by default, don't inject it
        // again
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "kimi-k2-thinking",
            R::High
        ));
    }

    #[test]
    fn dashscope_off_setting_skips() {
        // Respected when the user actively turns off thinking
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "qwen3-30b",
            R::Off
        ));
    }

    #[test]
    fn dashscope_non_reasoning_model_skips() {
        // Pure-chat models like qwen-turbo / qwen2.5 shouldn't be injected
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "qwen-turbo",
            R::High
        ));
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            DASHSCOPE_CN,
            "qwen2.5-72b",
            R::High
        ));
    }

    #[test]
    fn non_dashscope_url_skips() {
        // base_urls that aren't DashScope, like OpenAI / Cerebras / Groq
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            "https://api.openai.com/v1/",
            "qwen3-30b",
            R::High
        ));
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::OpenAi,
            "https://api.cerebras.ai/v1/",
            "qwen3-30b",
            R::High
        ));
    }

    #[test]
    fn non_openai_api_type_skips() {
        // Anthropic / Gemini / DeepSeek api_types don't take this path
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::Anthropic,
            DASHSCOPE_CN,
            "qwen3-30b",
            R::High
        ));
        assert!(!dashscope_needs_enable_thinking(
            AgentProviderApiType::DeepSeek,
            DASHSCOPE_CN,
            "deepseek-r1",
            R::High
        ));
    }
}

/// Regression tests for the "thinking-depth tier submission" in `build_chat_options`.
///
/// Aligned with how Zed's `LanguageModelRequest::thinking_allowed=false` is handled per
/// provider: **when Off, no provider should let the server think**. The concrete strategy
/// differs by provider:
/// - Anthropic / Gemini: no thinking field sent (skips `with_reasoning_effort`)
/// - DeepSeek: `extra_body.thinking.type=disabled` (on by default server-side, needs
///   explicit off)
/// - OpenAI / OpenAiResp: `reasoning_effort: "none"` (accepted by GPT-5)
#[cfg(test)]
mod build_chat_options_off_tests {
    use super::*;
    use crate::settings::ReasoningEffortSetting as R;
    use genai::chat::ReasoningEffort as GE;

    fn opts(api_type: AgentProviderApiType, model: &str, effort: R) -> genai::chat::ChatOptions {
        build_chat_options(
            api_type,
            "https://example.com/v1/",
            model,
            effort,
            vec![],
            None,
        )
    }

    /// claude-sonnet-4-6 (matches `SUPPORT_ADAPTTIVE_THINK_MODELS`) + Off must **not pass
    /// `reasoning_effort` at all**, or the vendor genai adapter unconditionally inserts
    /// `thinking:{type:adaptive}` (`adapter_impl.rs:121-135`).
    #[test]
    fn anthropic_sonnet_4_6_off_skips_reasoning_effort() {
        let o = opts(AgentProviderApiType::Anthropic, "claude-sonnet-4-6", R::Off);
        assert!(
            o.reasoning_effort.is_none(),
            "Anthropic+Off must not pass reasoning_effort, to avoid the 4.6 family forcibly \
             inserting adaptive thinking"
        );
        assert!(
            o.extra_body.is_none(),
            "Anthropic+Off also shouldn't inject extra_body"
        );
    }

    /// claude-opus-4-6, same as above (matches both SUPPORT_EFFORT and SUPPORT_ADAPTIVE).
    #[test]
    fn anthropic_opus_4_6_off_skips_reasoning_effort() {
        let o = opts(AgentProviderApiType::Anthropic, "claude-opus-4-6", R::Off);
        assert!(o.reasoning_effort.is_none());
        assert!(o.extra_body.is_none());
    }

    /// claude-opus-4-7+ + Off: even though it's not on the adaptive list (already fine
    /// either way), it should still consistently skip.
    #[test]
    fn anthropic_opus_4_7_off_skips_reasoning_effort() {
        let o = opts(AgentProviderApiType::Anthropic, "claude-opus-4-7", R::Off);
        assert!(o.reasoning_effort.is_none());
        assert!(o.extra_body.is_none());
    }

    /// Anthropic + High still takes the original reasoning_effort path.
    #[test]
    fn anthropic_high_injects_reasoning_effort() {
        let o = opts(AgentProviderApiType::Anthropic, "claude-opus-4-7", R::High);
        assert!(matches!(o.reasoning_effort, Some(GE::High)));
    }

    /// Anthropic + Auto doesn't pass any parameters.
    #[test]
    fn anthropic_auto_skips() {
        let o = opts(AgentProviderApiType::Anthropic, "claude-opus-4-7", R::Auto);
        assert!(o.reasoning_effort.is_none());
    }

    /// Gemini + Off: no thinkingConfig sent.
    #[test]
    fn gemini_off_skips_reasoning_effort() {
        let o = opts(AgentProviderApiType::Gemini, "gemini-2.5-pro", R::Off);
        assert!(o.reasoning_effort.is_none());
        assert!(o.extra_body.is_none());
    }

    /// Gemini + Medium takes the thinkingBudget path.
    #[test]
    fn gemini_medium_injects_reasoning_effort() {
        let o = opts(AgentProviderApiType::Gemini, "gemini-2.5-pro", R::Medium);
        assert!(matches!(o.reasoning_effort, Some(GE::Medium)));
    }

    /// DeepSeek + Off: must send `extra_body.thinking.type=disabled`, and **must not** take
    /// the reasoning_effort=none path (the server 400s with an unknown variant).
    #[test]
    fn deepseek_off_uses_extra_body_disabled() {
        let o = opts(AgentProviderApiType::DeepSeek, "deepseek-v4-flash", R::Off);
        assert!(
            o.reasoning_effort.is_none(),
            "DeepSeek+Off must not take the reasoning_effort=none path"
        );
        let body = o.extra_body.as_ref().expect("extra_body must be set");
        assert_eq!(
            body.pointer("/thinking/type"),
            Some(&serde_json::Value::String("disabled".to_string())),
            "DeepSeek+Off must send thinking.type=disabled"
        );
    }

    /// DeepSeek + High takes the reasoning_effort top-level field path.
    #[test]
    fn deepseek_high_injects_reasoning_effort() {
        let o = opts(AgentProviderApiType::DeepSeek, "deepseek-reasoner", R::High);
        assert!(matches!(o.reasoning_effort, Some(GE::High)));
        assert!(o.extra_body.is_none());
    }

    /// OpenAI (GPT-5) + Off: takes the reasoning_effort=none path (GPT-5 accepts the `none`
    /// tier).
    #[test]
    fn openai_gpt5_off_uses_reasoning_effort_none() {
        let o = opts(AgentProviderApiType::OpenAi, "gpt-5", R::Off);
        assert!(
            matches!(o.reasoning_effort, Some(GE::None)),
            "OpenAI+GPT-5+Off should send reasoning_effort=none"
        );
    }

    /// A model that doesn't support reasoning + any non-Auto tier: skipped (avoids a 400
    /// from upstream).
    #[test]
    fn anthropic_haiku_3_5_off_skips() {
        let o = opts(
            AgentProviderApiType::Anthropic,
            "claude-3-5-haiku-20241022",
            R::Off,
        );
        assert!(o.reasoning_effort.is_none());
        assert!(o.extra_body.is_none());
    }

    #[test]
    fn openai_gpt4o_off_skips() {
        // gpt-4o isn't on the reasoning list, so Off is skipped too
        let o = opts(AgentProviderApiType::OpenAi, "gpt-4o", R::Off);
        assert!(o.reasoning_effort.is_none());
    }
}

#[cfg(test)]
mod adapter_routing_tests {
    use super::*;
    use genai::adapter::AdapterKind;

    const OPENAI_HOST: &str = "https://api.openai.com/v1/";
    const ANTHROPIC_HOST: &str = "https://api.anthropic.com/v1/";
    const OPENROUTER_HOST: &str = "https://openrouter.ai/api/v1/";

    #[test]
    fn openai_gpt54_auto_upgrades_to_responses_api() {
        assert_eq!(
            effective_adapter_kind_for(AgentProviderApiType::OpenAi, "gpt-5.4", OPENAI_HOST),
            AdapterKind::OpenAIResp
        );
    }

    #[test]
    fn openai_gpt4o_stays_on_chat_completions() {
        assert_eq!(
            effective_adapter_kind_for(AgentProviderApiType::OpenAi, "gpt-4o", OPENAI_HOST),
            AdapterKind::OpenAI
        );
    }

    #[test]
    fn openai_resp_api_type_unchanged() {
        assert_eq!(
            effective_adapter_kind_for(AgentProviderApiType::OpenAiResp, "gpt-5.4", OPENAI_HOST),
            AdapterKind::OpenAIResp
        );
    }

    #[test]
    fn openai_claude_on_anthropic_host_auto_upgrades() {
        assert_eq!(
            effective_adapter_kind_for(
                AgentProviderApiType::OpenAi,
                "claude-sonnet-4-6",
                ANTHROPIC_HOST
            ),
            AdapterKind::Anthropic
        );
    }

    #[test]
    fn openai_claude_on_openrouter_stays_openai() {
        assert_eq!(
            effective_adapter_kind_for(
                AgentProviderApiType::OpenAi,
                "anthropic/claude-sonnet-4-6",
                OPENROUTER_HOST
            ),
            AdapterKind::OpenAI
        );
    }

    #[test]
    fn openai_gpt54_on_relay_host_stays_on_chat_completions() {
        // chat-completions-only relays like one-api / LiteLLM keep the official model id;
        // auto-upgrading to the Responses API must only take effect for the official host,
        // otherwise it 404s.
        assert_eq!(
            effective_adapter_kind_for(AgentProviderApiType::OpenAi, "gpt-5.4", OPENROUTER_HOST),
            AdapterKind::OpenAI
        );
    }

    #[test]
    fn anthropic_api_type_unchanged() {
        assert_eq!(
            effective_adapter_kind_for(
                AgentProviderApiType::Anthropic,
                "claude-opus-4-7",
                ANTHROPIC_HOST
            ),
            AdapterKind::Anthropic
        );
    }
}

